PAGES=[]
def P(slug,group,title,description,intro,sections,checks,faq,related):
    PAGES.append(dict(slug=slug,group=group,title=title,description=description,intro=intro,sections=sections,checks=checks,faq=faq,related=related))

P('veilingtransport-voertuigen','Voertuigen','Veilingvoertuig laten ophalen en vervoeren',
'Auto, motor, bestelwagen of camper op een veiling gekocht? Bereid uw voertuigtransport voor met ACR: toestand, laadwijze, afhaaldag en offerte.',
'Een gewonnen voertuig moet niet alleen van het veilingterrein weg: het moet ook op de afgesproken bestemming kunnen worden gelost. ACR beoordeelt uw aanvraag op het concrete voertuig, de beschikbare toegang en het afhaalvenster. Deze gids helpt u de juiste transportvraag samen te stellen.',[
('Kies op toestand, niet alleen op voertuigtype','Een personenwagen die normaal rijdt, vraagt een andere voorbereiding dan een wagen met geblokkeerde remmen. Noteer afzonderlijk of het voertuig start, rolt, stuurt en remt. Een korte vermelding als “defect” zegt daarvoor te weinig. Vermeld bij een automaat ook of de transmissie kan worden vrijgezet, zonder zelf een onveilige of onbekende procedure uit te proberen.'),
('Maten en massa bepalen de laadoplossing','Stuur merk, model en uitvoering door. Bij een bestelwagen zijn lengte en dakhoogte van belang; bij een camper tellen ook uitstekende dragers, dakuitrusting en de werkelijke massa mee. Accessoires in de auto of een extra set wielen moeten op de aanvraag staan. Zo wordt niet pas bij afhaling duidelijk dat meer ruimte nodig is.'),
('Van kavel naar garage, bedrijf of woning','Geef het echte afleveradres op en beschrijf de losplaats. Een transport naar een hersteller is pas praktisch als iemand de wagen kan aannemen en een niet-rijdend voertuig daar kan blijven staan. Bij levering aan huis zijn een verharde ondergrond, voldoende manoeuvreerruimte en een bereikbare ontvanger even belangrijk als de laadplaats.'),
('Laat de volledige opdracht bevestigen','Een aanvraag is nog geen ingeplande rit. Bezorg de kavelinformatie, vrijgave en tijdsbeperkingen voordat u de opdracht bevestigt. ACR stemt prijs en uitvoering met u af. De planning moet passen bij de afhaallocatie én bij de ontvanger; een gewonnen bod alleen garandeert geen plaats op een transport.')],
['Kavellink en herkenbaar kavelnummer','Merk, model, uitvoering en eventuele accessoires','Starten, rollen, sturen en remmen apart beschreven','Afhaalvenster en contactpersoon voor vrijgave','Bestemming, ondergrond en ontvanger'],
[('Kan elk voertuig met dezelfde transporter mee?','Nee. Afmetingen, massa, bodemvrijheid en technische toestand bepalen welke uitvoering haalbaar is. Een grote camper, geblokkeerde auto of brede buggy wordt afzonderlijk beoordeeld.'),('Moet de auto ingeschreven zijn voor transport?','Vervoer op een transportvoertuig is een andere vraag dan zelf over de openbare weg rijden. Meld de document- en inschrijvingssituatie; ACR bevestigt de transportwijze voor uw opdracht.')],
['veiling-auto-ophalen','niet-rijdende-veilingauto','camper-veiling-transport','veilingtransport-documenten'])

P('veilingtransport-goederen','Goederen','Goederen en machines van een veiling vervoeren',
'Veilinggoederen laten ophalen? ACR bekijkt pallets, machines en inventaris op maten, gewicht, verpakking, toegang en mogelijkheden bij laden en lossen.',
'Een kavel met goederen kan één verpakte pallet zijn, maar ook een verzameling losse machines en onderdelen. De naam van het kavel zegt weinig over de laadbaarheid. Voor een bruikbare transportaanvraag moet duidelijk zijn wat werkelijk klaarstaat, hoe het kan worden verplaatst en wie ter plaatse helpt.',[
('Maak van een kavel een concrete laadlijst','Splits uw aankoop op in transporteenheden: bijvoorbeeld twee pallets, één verrijdbare kast en drie losse dozen. Geef per eenheid buitenmaten en massa door. Vermeld uitstekende delen en of de verpakking voldoende bescherming biedt. Een totaalfoto is nuttig, maar vervangt geen telling of maten wanneer de laadruimte moet worden beoordeeld.'),
('Controleer de route tot aan het voertuig','Een machine in een kelder of achteraan een werkplaats is nog niet laadklaar. Beschrijf de verdieping, deuren, drempels, hellingen en de afstand tot de laadplaats. Vraag of een heftruck of ander hulpmiddel beschikbaar is, wie het bedient en of het voor deze lading geschikt is. Aanwezig materieel is niet automatisch inbegrepen.'),
('Transport en voorbereiding zijn aparte werkzaamheden','Demontage, het losmaken van aansluitingen, verpakken en hijsen worden niet stilzwijgend onderdeel van een rit. Leg vast wie die voorbereiding uitvoert en wanneer de goederen gereed zijn. Voor grote industriële installaties kan eerst gespecialiseerd werk nodig zijn. ACR bevestigt alleen de uitvoering die voor uw concrete aanvraag is afgesproken.'),
('Bereid ook de ontvangende locatie voor','Bepaal vooraf hoe de goederen van het transportvoertuig afkomen. Een heftruck aan de laadzijde lost geen probleem op een bestemming zonder loshulp op. Vermeld het ontvangstvenster, de manoeuvreerruimte en de plaats waar het kavel mag worden neergezet. Laat iemand de aantallen bij aflevering vergelijken met de afgesproken laadlijst.')],
['Aantal colli of transporteenheden per kavel','Buitenmaten en massa per eenheid','Verpakking en eventuele kwetsbare delen','Verplaatsing vanuit het gebouw tot aan de laadplaats','Laadhulp én loshulp met contactpersonen'],
[('Is verpakken standaard inbegrepen?','Alleen wanneer dat vooraf uitdrukkelijk is afgesproken. Beschrijf wat onverpakt klaarstaat en welke bescherming of voorbereiding nog nodig is.'),('Kan ik zware machines aanvragen?','Ja, u kunt de gegevens voor beoordeling bezorgen. Dat is geen automatische acceptatie: massa, toegang, laadwijze en benodigde specialistische werkzaamheden worden eerst gecontroleerd.')],
['pallet-veiling-transport','machine-veiling-transport','laden-lossen-veiling','meerdere-kavels-ophalen'])

P('veilingtransport-kosten','Voorbereiding','Wat kost transport van een veilingaankoop?',
'Welke gegevens bepalen de prijs van veilingtransport? Bekijk route, lading, afhaaltijd, laadwerk, wachttijd en hoe u offertes correct vergelijkt.',
'De transportprijs van een veilingkavel volgt niet alleen uit het aantal kilometers. De laadbaarheid, beschikbare tijd en losplaats kunnen even bepalend zijn. Met dezelfde gegevens in elke aanvraag kunt u prijzen beter vergelijken en verkleint u de kans op een onvolledige offerte.',[
('De route begint bij twee volledige adressen','Vermeld laad- en losadres met postcode, niet alleen de provincie of het land. Een extra stop, een omweg voor een tweede kavel en beperkte bereikbaarheid beïnvloeden de planning. Geef ook aan of het om één voertuig gaat of om verschillende transporteenheden. De voertuigkeuze moet immers passen bij de volledige opdracht.'),
('Een niet-rijdende auto is geen gewone laadstop','Een auto die niet start maar vrij rolt, verschilt van een wagen met vaststaande wielen. Hetzelfde geldt voor goederen: een verpakte pallet naast een laadpoort verschilt van een machine die nog uitgebouwd moet worden. Laat bijzondere handelingen apart omschrijven, zodat beide partijen weten welk werk in de prijs zit.'),
('Vergelijk de inbegrepen werkzaamheden','Controleer of laden, lossen, eventuele wachttijd en extra stops in de aangeboden uitvoering zijn opgenomen. Vraag hoe wijzigingen worden behandeld als de afhaalplaats andere informatie geeft dan de kavelomschrijving. Controleer ook of het genoemde bedrag inclusief of exclusief btw is; één kaal totaal zonder omschrijving maakt vergelijken moeilijk.'),
('Vraag een beoordeling voordat u uw bod bepaalt','Transport hoort bij uw aankoopbudget. Bezorg daarom al vóór de veiling de kavellink, route en afhaalvoorwaarden. Een voorlopige beoordeling kan nog wijzigen wanneer maten, toestand of timing anders blijken te zijn. Laat na toewijzing de actuele uitvoering en prijs bevestigen voordat u een transportopdracht als definitief beschouwt.')],
['Laadadres en losadres met postcode','Aantal voertuigen, pallets of losse eenheden','Werkelijke maten, massa en technische toestand','Vast tijdslot en eventuele extra stops','Omschrijving van inbegrepen werk en btw-behandeling'],
[('Staat er een vaste kilometerprijs op de site?','Nee. ACR geeft een prijs op basis van de volledige opdracht. Een kilometerbedrag zonder laadwijze, tijdslot en lading kan een verkeerd beeld geven van het totaal.'),('Is gecombineerd vervoer altijd goedkoper?','Dat hangt af van de route, beschikbare ruimte en afhaaldagen. Een combinatie moet praktisch passen en wordt pas na beoordeling bevestigd.')],
['veilingtransport-offerte-voor-bieden','meerdere-kavels-ophalen','niet-rijdende-veilingauto','laden-lossen-veiling'])

P('troostwijk-transport','Platformen','Troostwijk-kavel laten ophalen met ACR',
'Transport aanvragen voor een aankoop via Troostwijk: kavellink, afhaalvenster, vrijgave, laadmogelijkheden en levering vooraf afstemmen met ACR.',
'Een aankoop via Troostwijk kan een auto, machine of partij goederen zijn. ACR kan uw transportaanvraag beoordelen met de gegevens van het concrete kavel. U spreekt de rit rechtstreeks met ACR af; de aankoop en vrijgave blijven bij de verkoper en het veilingplatform.',[
('Begin met de actuele kavelgegevens','Bezorg de volledige kavellink en het kavelnummer, ook als u al een screenshot hebt doorgestuurd. Voeg de afhaalgegevens uit uw aankoopdocumenten toe. Een veilingnaam alleen is onvoldoende: verschillende kavels kunnen op andere adressen staan of andere handelingen vereisen. Vermeld duidelijk welke artikelen u daadwerkelijk hebt toegewezen gekregen.'),
('Stem het afhaalvenster met de rit af','Troostwijk publiceert afhaalinformatie bij de aankoop; controleer die informatie voor uw eigen kavel. Deel het tijdvak en de uiterste afhaaldatum voordat de rit wordt vastgelegd. Een transportaanvraag bij ACR verplaatst een afhaaldag niet. Bij tegenstrijdige of gewijzigde informatie laat u de verkoper of het platform de juiste afspraken bevestigen.'),
('Beschrijf wat op de laadplaats gereedstaat','Een veilingfoto zegt niet altijd hoe een kavel wordt aangeboden. Meld of goederen verpakt zijn en wie ze tot bij het voertuig brengt. Voor een auto geeft u afzonderlijk door of die kan starten, rollen, sturen en remmen. Voor een machine zijn een typeplaatfoto, buitenmaten en een overzicht van aansluitingen of losse delen nuttig.'),
('Maak van vrijgave en ontvangst twee duidelijke stappen','Zorg dat de afhaler de juiste vrijgavegegevens en een bereikbare contactpersoon heeft. Geef bij aflevering aan wie de goederen of het voertuig kan aannemen. Een kavel dat nog niet is vrijgegeven of waarvoor de ontvanger geen losmogelijkheid heeft, mag niet worden behandeld alsof de hele opdracht al uitvoerbaar is.')],
['Troostwijk-kavellink en kavelnummer','Afhaaldocument en bevestigd tijdvak','Gegevens over betalen en vrijgave voor afhaling','Toestand of verpakking van de aankoop','Laad- en loscontact met bereikbaar telefoonnummer'],
[('Is ACR de officiële transporteur van Troostwijk?','Deze website claimt geen officiële samenwerking of vertegenwoordiging. U vraagt onafhankelijk transport aan bij ACR; uw veilingaankoop regelt u met de betrokken partijen.'),('Kan ACR een afhaaldag wijzigen?','ACR kan de haalbare ritplanning met u bespreken, maar bepaalt niet de afhaalvoorwaarden van het platform of de verkoper. Laat afwijkingen daar eerst bevestigen.')],
['veilingtransport-documenten','afhaaldag-veiling-regelen','veilingtransport-voertuigen','veilingtransport-goederen'])

P('vavato-transport','Platformen','Vavato-aankoop laten ophalen en leveren',
'Vavato-kavel gewonnen? Bereid uw transportaanvraag bij ACR voor met de juiste afhaallocatie, vrijgave, verpakking en laad- en losmogelijkheden.',
'Een Vavato-kavel laten ophalen begint bij het echte afhaaladres en de manier waarop het kavel klaarstaat. ACR beoordeelt transport van voertuigen en goederen op basis van uw informatie. Een veilingnaam op de aanvraag vervangt geen omschrijving van de lading en de beschikbare hulp.',[
('Zet aankoopinformatie om in transportinformatie','Stuur de kavellink en maak een korte lijst van alle onderdelen die moeten worden meegenomen. Bij een partij inventaris kan het aantal fysieke eenheden sterk verschillen van het aantal kavels. Geef maten, massa, verpakking en kwetsbare delen mee. Gebruik recente foto’s als de oorspronkelijke presentatie niet toont hoe de spullen op afhaling klaarstaan.'),
('Controleer de verpakking vóór de rit','Vavato vraagt kopers om verpakking en transport duidelijk met de vervoerder af te stemmen. Ga daarom niet uit van een pallet, doos of beschermende verpakking die nergens is bevestigd. Vertel welke artikelen los liggen, welke delen breekbaar zijn en wie eventuele voorbereiding uitvoert. ACR beoordeelt daarna welke afgesproken uitvoering passend is.'),
('Leg toegang en ondersteuning vast','Vraag waar het kavel zich in het gebouw bevindt en hoe de laadplaats bereikbaar is. Een heftruck, laadperron of ruime parking kan het werk vereenvoudigen, maar de inzet ervan moet beschikbaar en geschikt zijn voor uw kavel. Ook aan de afleverzijde moeten hulp, ruimte en ontvangsttijd kloppen met de geplande rit.'),
('Houd de afspraken met het platform gescheiden','Bezorg de afhaalgegevens uit uw eigen documenten en meld wijzigingen direct. ACR bevestigt het vervoer, niet de koop of betalingsstatus. Heeft u nog geen vrijgave of is het afhaalvenster onzeker, dan moet dat eerst worden uitgeklaard. Veronderstel evenmin dat een transportaanvraag automatisch een reservering bij de afhaallocatie maakt.')],
['Vavato-kavellink met exacte selectie','Aantal fysieke eenheden en buitenmaten','Verpakkingsstatus en kwetsbare delen','Afspraak, vrijgavegegevens en locatiecontact','Losmogelijkheden op de uiteindelijke bestemming'],
[('Werkt ACR namens Vavato?','Nee, deze pagina biedt een onafhankelijke transportaanvraag. Er wordt geen officiële partnerschapstatus of plaats op een transporteurslijst geclaimd.'),('Kan onverpakte inventaris worden meegenomen?','Dat moet vooraf worden beoordeeld. Beschrijf welke bescherming en handelingen nodig zijn; verpakken of demonteren is alleen inbegrepen als het afzonderlijk is afgesproken.')],
['meerdere-kavels-ophalen','veilingtransport-checklist','pallet-veiling-transport','garage-inventaris-veiling-transport'])

P('auctim-transport','Platformen','Auctim-kavel laten ophalen door een transporteur',
'Auctim-aankoop laten vervoeren? Geef afgiftedocument of QR-code, afhaaldag, lading en laadmogelijkheden door voor een transportbeoordeling door ACR.',
'Kunt u uw Auctim-aankoop niet zelf ophalen, dan kunt u een transporteur inschakelen. De afhaling moet passen binnen de voorwaarden van uw kavel. ACR beoordeelt de rit met uw afgiftegegevens, route en een concrete beschrijving van wat ter plaatse klaarstaat.',[
('Neem het afgiftedocument als uitgangspunt','Auctim verwijst voor afhaling door een derde naar het afgiftedocument of de QR-code. Zorg dat die gegevens beschikbaar zijn voor de persoon die daadwerkelijk ophaalt. Controleer ook of uw aankoop vrijgegeven is en of alle door u opgegeven kavels op hetzelfde document en hetzelfde adres staan. Stuur geen accountwachtwoorden mee met een transportaanvraag.'),
('Laat de gespecificeerde datum de planning bepalen','De gepubliceerde afgiftemomenten zijn het vertrekpunt voor de ritplanning. Een gewenste vervoersdatum betekent niet dat de afhaalplaats op die dag open is. Deel het juiste venster meteen met ACR. Als de informatie niet overeenkomt met wat u van een contactpersoon verneemt, laat de actuele afspraak door de betrokken partij bevestigen.'),
('Regel laden op basis van de werkelijke locatie','Beschrijf verdieping, toegang, afmetingen en massa van de aankoop. Controleer expliciet of er transportapparatuur beschikbaar is en wie deze mag bedienen. Voor goederen die nog moeten worden losgemaakt of verplaatst, moeten die werkzaamheden apart worden geregeld. Een grote machine is niet automatisch een gewone laadopdracht omdat zij als één kavel werd verkocht.'),
('Maak levering tot onderdeel van dezelfde aanvraag','Bezorg direct de uiteindelijke bestemming, zodat laadruimte en ontvangst kunnen worden afgestemd. Meld een smalle toegangsweg, een ontbrekende loshulp of een beperkt ontvangstvenster vooraf. ACR bevestigt welke transportuitvoering haalbaar is. U behoudt zelf de afspraken over koop, betaling en vrijgave met het veilingplatform en de verkoper.')],
['Auctim-kavellink en kavelnummer','Afgiftedocument of QR-code voor de afhaler','Gepubliceerd afhaalvenster en locatie','Massa, maten, verdieping en toegang','Naam van ontvanger en bevestigde loshulp'],
[('Is ACR onderdeel van Auctim?','Nee. ACR is de partij bij wie u onafhankelijk transport aanvraagt. De naam van het platform wordt gebruikt om de voorbereiding van uw afhaling te verduidelijken.'),('Is laadmaterieel standaard aanwezig?','Ga daar niet van uit. Controleer de specifieke kavelinformatie en vraag welke hulpmiddelen voor uw afhaling daadwerkelijk beschikbaar zijn.')],
['veilingtransport-documenten','laden-lossen-veiling','machine-veiling-transport','afhaaldag-veiling-regelen'])

P('veiling-auto-ophalen','Voertuigen','Auto op een veiling gekocht: laten ophalen',
'Veilingauto laten ophalen bij verkoper of veilingterrein? ACR bespreekt afhaling, transport naar garage of thuisadres, documenten en voertuigtoestand.',
'Een auto op een veiling kopen en de auto ophalen zijn twee verschillende stappen. Vóór de rit moeten vrijgave, tijdslot en voertuigtoestand helder zijn. Met die gegevens kan ACR bepalen hoe de wagen van de verkoper naar uw garage, bedrijf of thuisadres kan worden vervoerd.',[
('Controleer wat “rijdend” voor uw auto betekent','Vraag of de auto op de afhaaldag zelf kan worden verplaatst, en door wie. Een motor die bij een kijkdag even draaide, bevestigt niet dat remmen, stuurinrichting en wielen normaal werken. Beschrijf daarom starten, rollen, sturen en remmen apart. Meld een lege accu of een band die geen druk houdt voordat de transportuitvoering wordt afgesproken.'),
('Laat sleutels en documenten klaarleggen','Noteer hoeveel sleutels volgens de verkoper aanwezig zijn en welke documenten bij de wagen worden meegegeven. Vermeld ontbrekende stukken op de aanvraag. De afhaler moet de juiste auto en het juiste kavel kunnen identificeren. Voor vrijgave zijn de gegevens van uw aankoop belangrijk; een mondelinge beschrijving van kleur en model is daarvoor niet altijd voldoende.'),
('Kies een bestemming waar de wagen kan worden aangenomen','Gaat de auto naar een hersteller, stem de ontvangst vooraf met die garage af. Vermeld of een medewerker aanwezig is en waar een niet-rijdende auto mag worden geplaatst. Bij een thuisadres moet voldoende ruimte zijn om te manoeuvreren. Geef extra onderdelen en losse wielen op als zij met de auto mee moeten.'),
('Bevestig de rit pas met actuele informatie','Bezorg de kavellink, beide adressen en het afhaalvenster aan ACR. Als de toestand na de veiling verandert, bijvoorbeeld doordat een accu leeg raakt of een sleutel ontbreekt, meld dat vóór vertrek. De afgesproken prijs en uitvoering steunen op die gegevens; een afwijking op het terrein kan een andere laadoplossing nodig maken.')],
['Kavelnummer en herkenbare voertuiggegevens','Aanwezige sleutels en meegeleverde documenten','Rijdbaarheid en bandentoestand op de afhaaldag','Contactpersoon die de wagen vrijgeeft','Bestemming met ruimte en bevestigde ontvangst'],
[('Kan de auto rechtstreeks naar mijn garage?','Dat kunt u aanvragen. Bezorg het garageadres, de openingsuren en een contactpersoon; de garage moet de auto op het afgesproken moment kunnen aannemen.'),('Kan ik transport boeken voordat ik de factuur heb?','U kunt de rit laten beoordelen, maar de afhaling kan pas worden uitgevoerd wanneer de vereiste vrijgave en afspraken in orde zijn.')],
['niet-rijdende-veilingauto','veilingauto-zonder-sleutel','veilingtransport-documenten','veilingtransport-kosten'])

P('niet-rijdende-veilingauto','Voertuigen','Niet-rijdende veilingauto laten vervoeren',
'Veilingauto start niet of heeft vaststaande wielen? Beschrijf rollen, sturen, remmen en toegang voor een passende transportbeoordeling door ACR.',
'“Niet-rijdend” kan betekenen dat een auto niet start, maar ook dat hij helemaal niet kan rollen of sturen. Dat verschil bepaalt de voorbereiding en de laadwijze. ACR wil daarom de feitelijke beperkingen kennen voordat een rit en prijs worden bevestigd.',[
('Maak onderscheid tussen starten en verplaatsen','Een auto met een lege accu kan mogelijk nog vrij rollen. Een defecte versnellingsbak, vaststaande parkeerrem of geblokkeerd wiel kan dat juist verhinderen. Vermeld per onderdeel wat bekend is en wat nog moet worden gecontroleerd. Laat onbekende systemen door een geschikte persoon beoordelen; forceer geen transmissie of rem om alleen de transportaanvraag te vereenvoudigen.'),
('Beschrijf de plek waar de auto staat','Foto’s van rondom de wagen en van de aanrijroute helpen om de bereikbaarheid te beoordelen. Meld of de auto tussen andere voertuigen staat, in een afgesloten gebouw of op een helling. De laadplek moet toegankelijk zijn op het geboekte moment. Alleen een oude veilingfoto van de auto vertelt niets over de ruimte die bij afhaling beschikbaar is.'),
('Meld bijkomende schade en lekkage','Schade aan ophanging of wielen kan de manier van verplaatsen veranderen. Geef zichtbare lekkages, losse onderdelen en eventuele accuschade bij elektrische voertuigen door. De aanvraag moet passen bij de actuele toestand. Is de informatie onvolledig, vraag de verkoper dan om controle of aanvullende foto’s voordat u een gewone afhaling laat inplannen.'),
('Bereid het lossen net zo zorgvuldig voor','Kies een bestemming waar een niet-rijdende wagen veilig kan worden geplaatst en later verder behandeld. Een garage moet weten wat zij ontvangt en of de auto nog kan rollen. Spreek de plek van aflevering af. Het oplossen van het technische defect of verplaatsen binnen de werkplaats is geen vanzelfsprekend onderdeel van het transport.')],
['Start niet: bekende oorzaak of onbekend','Vrij rollen, sturen en remmen afzonderlijk','Parkeerrem, transmissie en sleutelstatus','Foto’s van voertuig en directe omgeving','Losplaats geschikt voor een niet-rijdende auto'],
[('Kunnen vaststaande wielen een probleem zijn?','Ja. Vermeld welke wielen vaststaan en waardoor, als dat bekend is. De laadwijze moet daarop worden afgestemd; het is geen normale rijdende laadstop.'),('Is een lege accu altijd eenvoudig op te lossen?','Dat kan niet op afstand worden gegarandeerd. Meld het probleem en de overige voertuigtoestand; een transportopdracht is geen belofte van reparatie of pechherstel ter plaatse.')],
['schadeauto-veiling-transport','veilingauto-zonder-sleutel','elektrische-veilingauto-transport','laden-lossen-veiling'])

P('schadeauto-veiling-transport','Voertuigen','Schadeauto van een veiling laten ophalen',
'Schadeauto gekocht op een veiling? ACR beoordeelt transport met foto’s, wiel- en ophangingsschade, lekkages, losse delen en een geschikte losplaats.',
'Bij een schadeauto is de zichtbare carrosserieschade maar een deel van de transportvraag. Wielstand, ophanging, lekkages en losse onderdelen kunnen bepalen of en hoe de auto kan worden geladen. Beschrijf de huidige toestand, ook als de veilingomschrijving daar weinig over zegt.',[
('Fotografeer meer dan de beschadigde zijde','Bezorg beelden van alle zijden, de wielen en de ruimte waar de wagen staat. Een zijaanzicht alleen laat bijvoorbeeld niet zien of een wiel tegen de carrosserie klemt. Meld ook scherpe of loshangende delen. Vraag de verkoper om recente foto’s als het voertuig na de veiling is verplaatst of gedeeltelijk gedemonteerd.'),
('Geef door wat nog functioneert','Noteer of de auto kan rollen, sturen en remmen en of de parkeerrem vrij is. Beschrijf bekende schade aan assen en ophanging. Een ontbrekend wiel, ingezakte veerpoot of geblokkeerd stuur vraagt een andere beoordeling dan een beschadigde bumper. Laat de uitvoering vooraf bevestigen; de naam “schadeauto” geeft op zichzelf geen volledige laadopdracht.'),
('Meld stoffen en onderdelen die apart aandacht vragen','Vermeld zichtbare lekkages en los mee te nemen onderdelen. Bij een elektrisch of hybride voertuig geeft u bekende schade aan het accupakket en relevante waarschuwingen onmiddellijk door. Een gewone transportaanvraag houdt niet automatisch in dat een voertuig met een beschadigde hoogspanningsaccu geaccepteerd kan worden. De toestand moet eerst duidelijk zijn.'),
('Stem aflevering af met de hersteller','De ontvangende garage of schadehersteller moet weten hoe de auto wordt aangeboden. Geef aan waar hij kan worden neergezet en wie aanwezig is. Maak ook een lijst van losse sleutels, documenten en onderdelen die samen met de wagen worden overgedragen. Zo kunt u bij aflevering concreet controleren of de afgesproken eenheden zijn aangekomen.')],
['Recente foto’s rondom en van beschadigde wielen','Rollen, sturen, remmen en aanwezige sleutels','Zichtbare lekkages en losse carrosseriedelen','Bekende accuschade bij elektrisch of hybride','Hersteller, losplek en lijst van losse onderdelen'],
[('Is een veilingfoto genoeg voor de beoordeling?','Niet altijd. Vraag aanvullende beelden van wielstand, onderzijde voor zover veilig zichtbaar, en de huidige standplaats. Een foto moet de laadbaarheid helpen verklaren.'),('Wordt elke schadeauto vervoerd?','Dat wordt niet vooraf gegarandeerd. De werkelijke toestand, benodigde ondersteuning en risico’s moeten passen bij de bevestigde uitvoering.')],
['niet-rijdende-veilingauto','elektrische-veilingauto-transport','veilingtransport-kosten','veilingtransport-checklist'])

P('veilingauto-zonder-sleutel','Voertuigen','Veilingauto zonder sleutel laten ophalen',
'Auto zonder sleutel op een veiling gekocht? Controleer stuurslot, parkeerrem, transmissie, toegang en vrijgave voordat u transport bij ACR aanvraagt.',
'Een ontbrekende sleutel kan gevolgen hebben voor stuurinrichting, parkeerrem en transmissie. Het is daarom een essentieel gegeven op uw transportaanvraag. ACR beoordeelt de afhaling op wat nog vrij kan bewegen en op de ondersteuning die voor het concrete voertuig nodig is.',[
('Maak de sleutelstatus precies','Er is verschil tussen een kwijtgeraakte afstandsbediening, een sleutel zonder werkende elektronica en een auto waarbij helemaal geen sleutel is. Meld ook of de deuren en motorkap bereikbaar zijn. Geef geen toezegging dat de auto “wel loskomt” zonder bevestiging. Voor de laadplanning is de werkelijk bekende toestand belangrijker dan een veronderstelling over het systeem.'),
('Controleer sloten en remmen zonder te forceren','Laat vaststellen of het stuur vergrendeld is, of de parkeerrem vrij is en of de transmissie kan worden vrijgezet volgens een geschikte procedure. Laat dit bij twijfel door de verkoper of een bevoegde vakman beoordelen. Deze pagina geeft geen instructies om sloten te omzeilen of beveiligingen uit te schakelen; het transport moet op een gecontroleerde manier uitvoerbaar zijn.'),
('Vrijgave blijft nodig, ook als er geen sleutel is','Zorg voor de juiste kavel- en aankoopgegevens en een contactpersoon op de afhaallocatie. De afhaler moet weten om welk voertuig het gaat en dat het mag worden meegenomen. Een ontbrekende sleutel verandert niets aan die voorbereiding. Meld of er losse onderdelen of documenten in een afgesloten voertuig liggen en hoe deze worden overgedragen.'),
('Vertel de ontvanger wat hij krijgt','Een garage of bedrijf dat de wagen ontvangt, moet weten dat hij zonder sleutel wordt aangeboden. Stem vooraf af waar de auto kan worden geplaatst en welke beweging nog mogelijk is. Het maken, inleren of vervangen van een sleutel valt niet automatisch onder de transportopdracht en moet afzonderlijk worden geregeld.')],
['Geheel geen sleutel of alleen elektronische storing','Deuren, motorkap en toegang tot losse documenten','Bekende stand van stuur, transmissie en parkeerrem','Aankoopvrijgave en voertuigidentificatie','Ontvanger geïnformeerd over ontbrekende sleutel'],
[('Kunnen jullie de auto zonder sleutel ophalen?','Dat kan worden beoordeeld, maar hangt af van het voertuig en de laadbaarheid. Stuur de gegevens over stuur, remmen, transmissie en standplaats voordat u de rit bevestigt.'),('Is sleutelvervanging inbegrepen?','Nee, niet zonder een afzonderlijke afspraak. De transportaanvraag beschrijft de afhaling en levering van het voertuig in de gemelde toestand.')],
['niet-rijdende-veilingauto','veiling-auto-ophalen','veilingtransport-documenten','veilingtransport-kosten'])

P('elektrische-veilingauto-transport','Voertuigen','Elektrische veilingauto laten transporteren',
'Elektrische of hybride auto op een veiling gekocht? Meld accustatus, storingen, rijdbaarheid, laadkabels en bekende accuschade voor beoordeling door ACR.',
'Een elektrische veilingauto kan een gewone rijdende aankoop zijn, maar ook een wagen met een lege accu of onbekende storing. De transportaanvraag moet dat verschil duidelijk maken. Geef zowel de aandrijving als de actuele toestand door; een modelnaam of actieradius uit de advertentie is niet voldoende.',[
('Beschrijf de actuele toestand van de wagen','Noteer of de auto inschakelt en of de transmissie, parkeerrem en stuurinrichting normaal reageren. Een laag laadniveau en een technische storing zijn verschillende situaties. Laat de verkoper aangeven wat op de afhaaldag werkelijk is getest. Vermeld ook of het voertuig bereikbaar is zonder eerst andere voertuigen te verplaatsen.'),
('Meld bekende schade aan batterij en onderzijde','Bezorg relevante foto’s en informatie uit de kavelbeschrijving. Een beschadigde of verdachte hoogspanningsaccu vraagt een afzonderlijke beoordeling en is geen vanzelfsprekende gewone transportopdracht. Raak beschadigde hoogspanningsonderdelen niet aan en probeer geen waarschuwing te verhelpen om de auto alleen laadbaar te laten lijken. De transportwijze wordt pas na beoordeling bevestigd.'),
('Laadkabels en accessoires horen op de lijst','Geef mee welke kabels, adapters en losse onderdelen volgens de aankoop bij de wagen horen. Vraag waar ze klaarliggen en laat aantallen bij de overdracht vergelijken. Het opladen van de auto op de afhaallocatie of onderweg is niet automatisch onderdeel van transport; bespreek vooraf welke voorbereiding nodig en mogelijk is.'),
('Laat lossen en verdere behandeling aansluiten','De ontvangende partij moet weten of de auto kan rollen en waar hij mag worden geplaatst. Een garage die een storingsvoertuig ontvangt, heeft andere informatie nodig dan een koper die een rijdende auto thuis verwacht. Bezorg de contactpersoon en het ontvangstvenster tegelijk met de aanvraag voor de afhaling.')],
['Elektrisch of hybride, met exacte uitvoering','Actuele inschakelbaarheid en bekende storingen','Parkeerrem, transmissie en vrije wielbeweging','Bekende batterijschade of schade aan de onderzijde','Kabels, accessoires en geïnformeerde ontvanger'],
[('Kan een elektrische auto met een lege accu worden opgehaald?','Dat kan worden beoordeeld. Vertel wat nog functioneert en of de wagen kan rollen, sturen en remmen. Alleen “accu leeg” geeft onvoldoende informatie voor een laadplan.'),('Kan een auto met accuschade als gewone auto mee?','Dat wordt niet aangenomen. Meld alle bekende schade vooraf; de aanvraag moet afzonderlijk op uitvoerbaarheid worden beoordeeld.')],
['niet-rijdende-veilingauto','schadeauto-veiling-transport','veilingauto-zonder-sleutel','veilingtransport-documenten'])

P('bestelwagen-veiling-transport','Voertuigen','Bestelwagen van een veiling laten ophalen',
'Veilingbestelwagen vervoeren? Geef lengte, dakhoogte, massa, inrichting en rijdbaarheid door. ACR beoordeelt afhaling en levering op uw concrete voertuig.',
'Een bestelwagen heeft vaak meer uitvoeringsvarianten dan een personenauto: kort of lang, laag of hoog dak en met of zonder zware inrichting. Daardoor zegt alleen het model onvoldoende over de benodigde laadruimte. ACR beoordeelt de rit met de echte uitvoering en actuele toestand van uw veilingaankoop.',[
('Vermeld de volledige uitvoering','Stuur de beschikbare voertuiggegevens, buitenmaten en foto’s. Denk ook aan een imperiaal, ladderrek, trekhaak of andere uitstekende uitrusting. Een verlengde of verhoogde bestelwagen kan een andere laadoplossing vragen dan de korte versie van hetzelfde model. Geef de gegevens uit de kavelomschrijving als uitgangspunt en meld wat nog niet is bevestigd.'),
('Beschrijf wat in de laadruimte blijft','Werkplaatsinrichting, stellingen, gereedschap en losse goederen kunnen de werkelijke massa en voorbereiding veranderen. Noteer wat bij de koop hoort en wat vóór transport wordt verwijderd. Een laadruimte die op de foto leeg lijkt, is geen garantie voor de toestand bij afhaling. Losse spullen moeten apart worden benoemd en geschikt zijn voor de afgesproken uitvoering.'),
('Controleer ondergrond en rijdbaarheid','Geef door of de wagen start, rolt, stuurt en remt. Meld een lege accu, vaststaande parkeerrem of platstaande banden afzonderlijk. Vertel waar hij op het terrein staat en hoe de laadplaats wordt bereikt. Bij een bedrijfsgebouw zijn ook poorthoogte, toegangsregeling en een beschikbaar afhaalcontact van belang.'),
('Stem de bestemming af op het formaat','Vraag of de ontvangende garage of het bedrijf plaats heeft voor deze uitvoering. Een hoge bestelwagen kan niet vanzelf een werkplaats in die voor personenauto’s is ingericht. Geef het ontvangstvenster en de gewenste losplaats door. De transportaanvraag omvat geen belofte dat het voertuig na aflevering direct in gebruik kan worden genomen.')],
['Korte of lange uitvoering en dakhoogte','Totale buitenmaten inclusief rekken en accessoires','Inrichting en losse inhoud van de laadruimte','Werkelijke massa voor zover bekend','Rollen, sturen, remmen en passende losplaats'],
[('Is het model voldoende voor een offerte?','Nee. De uitvoering, maten en inrichting kunnen sterk verschillen. Voeg duidelijke foto’s en de beschikbare voertuiggegevens toe.'),('Kunnen gereedschappen in de bestelwagen blijven?','Meld alle inhoud vooraf en stem verpakking en bevestiging af. Losse goederen worden niet zonder beoordeling als vanzelfsprekend onderdeel van de rit beschouwd.')],
['veilingtransport-voertuigen','veilingtransport-kosten','garage-inventaris-veiling-transport','veilingtransport-checklist'])

P('motor-veiling-transport','Voertuigen','Motor van een veiling laten ophalen',
'Motorfiets, scooter of brommer op een veiling gekocht? Bespreek afhaling met ACR: gewicht, breedte, stuurbeweging, schade, sleutels en accessoires.',
'Een veilingmotor vraagt een andere voorbereiding dan een auto of een pallet. Stabiliteit, wielbeweging en de beschikbare bevestigingsmogelijkheden zijn belangrijk voor de transportbeoordeling. Beschrijf de motor zoals hij op de afhaaldag klaarstaat, inclusief koffers, losse delen en eventuele schade.',[
('Geef uitvoering en massa door','Een lichte scooter en een zware toermotor stellen andere eisen aan laadruimte en handling. Vermeld merk, model, uitvoering en beschikbare massa-informatie. Geef de breedte inclusief koffers of uitstekende delen op. Stuur foto’s van beide zijden en van de voorkant, zodat de aanvraag meer informatie biedt dan alleen een handelsnaam.'),
('Controleer of de motor kan worden verplaatst','Meld of de wielen vrij draaien, het stuur beweegt en de remmen bruikbaar zijn. Een stuurslot zonder sleutel, een vaststaande rem of schade aan de voorvork kan extra voorbereiding vragen. Laat onbekende technische problemen niet tot op de afhaaldag onbesproken. Vermeld ook of de motor zelfstandig stabiel kan worden neergezet.'),
('Spreek accessoires en documenten af','Maak een lijst van sleutels, documenten, bagagekoffers, losse kuipdelen en andere mee te nemen onderdelen. Geef aan wat gemonteerd blijft en wat apart wordt aangeboden. Losse artikelen moeten als afzonderlijke transporteenheden kunnen worden beoordeeld. De aankoopbeschrijving alleen zegt niet hoe alles op het terrein aan de afhaler wordt overgedragen.'),
('Een duidelijke ontvangst voorkomt improvisatie','De afleverplaats moet bereikbaar zijn en geschikt om de motor aan te nemen. Geef trappen, smalle doorgangen en een hellende ondergrond vooraf door. Aflevering is iets anders dan het binnenplaatsen op een moeilijk bereikbare verdieping. Wilt u uitsluitend een afzonderlijke motortransportrit bespreken, dan kan dat ook via MotoExpress binnen het ACR-netwerk.')],
['Merk, model, massa en breedte met accessoires','Vrije wiel- en stuurbeweging','Aanwezige sleutels en eventueel stuurslot','Schade aan voorvork, wielen of kuipdelen','Lijst van koffers, losse onderdelen en documenten'],
[('Kan een motor zonder sleutel worden opgehaald?','Geef aan of het stuurslot actief is en of de motor kan rollen. ACR beoordeelt de benodigde uitvoering voordat de rit wordt bevestigd.'),('Kan ik meer dan één motor aanvragen?','Ja. Geef voor elke motor gegevens en toestand door, samen met alle laad- en losadressen. De combinatie wordt op ruimte en planning beoordeeld.')],
['quad-buggy-veiling-transport','veilingauto-zonder-sleutel','meerdere-kavels-ophalen','veilingtransport-documenten'])

P('quad-buggy-veiling-transport','Voertuigen','Quad of buggy van een veiling vervoeren',
'Quad, buggy, UTV of trike laten ophalen na een veiling? Geef buitenmaten, massa, rolkooi, wielbeweging en de ondergrond op beide adressen door.',
'Quads en buggy’s passen niet automatisch op dezelfde laadpositie als een motor of personenauto. Brede banden, een rolkooi en een lage onderzijde kunnen de transportkeuze bepalen. ACR bekijkt de concrete afmetingen en toestand voordat de uitvoering wordt afgesproken.',[
('Meet het voertuig inclusief uitstekende delen','Gebruik de grootste breedte, lengte en hoogte zoals het voertuig vervoerd wordt. Neem spatborden, spiegels, dragers, rolkooi en accessoires mee in de maten. Meld of onderdelen volgens afspraak worden verwijderd. Een opgegeven catalogusmaat kan afwijken van een aangepaste buggy; recente foto’s maken dat verschil zichtbaar.'),
('Vrij rollen is belangrijker dan een startbewijs','Een voertuig kan niet starten en toch verplaatsbaar zijn. Omgekeerd kan een draaiende motor niets zeggen over een geblokkeerde aandrijving of vaststaande rem. Beschrijf afzonderlijk wat bekend is over wielen, stuur en remmen. Vermeld schade, zachte banden en een lage bodemvrijheid zonder ervan uit te gaan dat dit ter plaatse eenvoudig te corrigeren is.'),
('Meld de toegang tot de afhaallocatie','Quads kunnen achteraan een erf of op een onverharde standplaats staan. Geef de route naar het laadpunt, poortbreedte en ondergrond aan. Vraag of de verkoper het voertuig tot op een bereikbare plek kan brengen en wie bij de afhaling aanwezig is. Dat moet passen bij het tijdvenster van de veiling.'),
('Laat losse uitrusting meetellen','Denk aan een losse lier, reservewielen, laadbakdelen of extra banden. Noteer wat bij het kavel hoort en hoe het wordt aangeboden. Geef ook de uiteindelijke losplaats op: een voertuig op transport afleveren betekent niet vanzelf dat het via een smalle doorgang in een achtertuin kan worden geplaatst.')],
['Totale maten met rolkooi, dragers en banden','Massa en eventuele aanpassingen aan het voertuig','Rollen, sturen, remmen en bodemvrijheid','Verharde of onverharde standplaats','Losse uitrusting en route tot de losplek'],
[('Wordt een UTV als motor behandeld?','Niet automatisch. De maten, massa en uitvoering zijn bepalend, ongeacht de benaming die het veilingplatform gebruikt.'),('Kan een brede buggy mee in gecombineerd vervoer?','Dat moet op de werkelijke laadruimte worden beoordeeld. Geef volledige maten en foto’s mee voordat een combinatie wordt bevestigd.')],
['motor-veiling-transport','veilingtransport-voertuigen','laden-lossen-veiling','veilingtransport-kosten'])

P('camper-veiling-transport','Voertuigen','Camper of mobilhome van een veiling vervoeren',
'Veilingcamper of mobilhome laten ophalen? ACR beoordeelt totale afmetingen, werkelijke massa, overhang, dakuitrusting en rijdbaarheid vóór transport.',
'Een camper of mobilhome is niet simpelweg een grote personenwagen. Hoogte, massa, overhang en uitrusting kunnen bepalen welke transportuitvoering mogelijk is. Een aanvraag bij ACR begint daarom met concrete voertuiggegevens en beelden van de hele opbouw, niet alleen met het merk van de basiswagen.',[
('Neem alle uitrusting in de maten op','Geef de totale lengte, breedte en hoogte door, inclusief fietsendrager, airco, antenne en andere dakdelen. Vermeld accessoires die uitsteken of apart worden meegenomen. Bij een lage bodemvrijheid of lange achteroverhang is ook een zijaanzicht nuttig. Veronderstel niet dat opgegeven catalogusmaten overeenkomen met de toestand waarin de camper wordt aangeboden.'),
('Maak de massa zo duidelijk mogelijk','Bezorg de beschikbare voertuigdocumenten en massa-informatie. Ingebouwde inrichting, extra uitrusting en achtergebleven goederen kunnen meespelen in de werkelijke massa. Als gegevens onzeker zijn, meld dat expliciet. Een grote mobilhome wordt niet zonder beoordeling ingepland op een plaats die bedoeld is voor een gewone auto.'),
('Beschrijf technische toestand en opbouwschade','Geef aan of de camper start, rolt, stuurt en remt. Meld beschadigde ramen, losse panelen, lekkages en schade aan chassis of ophanging. De opbouw moet geschikt zijn voor de afgesproken transportwijze. Repareren, afdichten of vastzetten van onbekende schade valt niet stilzwijgend onder een gewone afhaalopdracht.'),
('Plan een passende afleverplek','Een brede of hoge camper vraagt ruimte voor aankomst en lossen. Stuur gegevens over poorten, bomen, hellingen en de ondergrond op de bestemming. Stem ontvangst af met de eigenaar of hersteller. ACR bevestigt de haalbare uitvoering voor deze camper; beschikbaarheid en prijs volgen uit de volledige opdracht.')],
['Totale hoogte met dakuitrusting','Lengte met dragers en uitstekende delen','Massa-informatie en aanwezige losse inhoud','Bodemvrijheid en achteroverhang','Opbouwschade, toegang en geschikte losplaats'],
[('Kan elke camper op een autotransporter mee?','Nee. Totale maten, massa en constructie moeten eerst passen bij een geschikte laadoplossing. De uitvoerbaarheid wordt afzonderlijk bevestigd.'),('Kan een niet-rijdende mobilhome worden aangevraagd?','Ja, bezorg de technische toestand en beschikbare voertuiggegevens. Niet-rijdend vervoer is geen automatische toezegging voor elke afmeting of schade.')],
['caravan-veiling-transport','niet-rijdende-veilingauto','veilingtransport-spanje','veilingtransport-checklist'])

P('caravan-veiling-transport','Voertuigen','Caravan op een veiling gekocht: transport regelen',
'Caravan van een veiling ophalen? Geef totale lengte, breedte, massa, koppeling, wieltoestand en eventuele schade door voor beoordeling door ACR.',
'Een caravan heeft andere aandachtspunten dan een zelfrijdend voertuig. De toestand van onderstel, banden en koppeling bepaalt mee hoe de afhaling kan worden uitgevoerd. ACR bespreekt de passende transportwijze nadat de kavelgegevens en route duidelijk zijn.',[
('Vermeld maten inclusief dissel en uitrusting','De totale lengte met dissel is belangrijker dan alleen de lengte van het woongedeelte. Geef ook de grootste breedte, hoogte en de beschikbare massa-informatie door. Meld fietsenrekken, reservewielen of losse uitrusting. Bij twijfel kunnen foto’s en beschikbare documenten helpen, maar ontbrekende gegevens moeten nog vóór het definitief vastleggen worden opgehelderd.'),
('Veronderstel geen rijklaar onderstel','Een caravan die lang heeft stilgestaan, kan problemen hebben die niet zichtbaar zijn op een overzichtsfoto. Vraag naar banden, wielbeweging, remmen en de koppeling. Meld vlakke banden, een vaststaande parkeerrem of zichtbare onderstelschade. Een transportaanvraag houdt niet in dat de caravan automatisch geschikt is om op eigen wielen over de openbare weg te worden getrokken.'),
('Neem de toestand van de opbouw mee','Beschrijf losse luiken, beschadigde ramen, uitstekende panelen en losse inhoud. Laat vóór transport vaststellen wat nog moet worden voorbereid. De afhandeling van onbekende of loshangende schade is geen vanzelfsprekende aanvulling op een rit. Stem ook af wie de caravan vanuit de standplaats naar het laadpunt kan brengen.'),
('Geef een bestemming met manoeuvreerruimte','Een smalle campingtoegang of krappe binnenplaats kan de aflevering anders maken dan een ruim bedrijfsterrein. Vermeld poorten, scherpe bochten, hellingen en de ondergrond. Spreek af wie de caravan ontvangt en waar hij mag blijven staan. Binnenplaatsen buiten de afgesproken losplek vraagt aparte beoordeling.')],
['Lengte inclusief dissel en accessoires','Breedte, hoogte en beschikbare massa-informatie','Banden, remmen, wielbeweging en koppeling','Bekende schade aan onderstel en opbouw','Ruimte en ondergrond op de bestemming'],
[('Wordt de caravan altijd getrokken?','Nee. De transportwijze volgt uit de technische toestand, gegevens en afspraken. Geschiktheid voor vervoer op eigen wielen wordt niet aangenomen op basis van een veilingfoto.'),('Kan de caravan naar een stalling worden geleverd?','Dat kunt u aanvragen. Bezorg toegangsgegevens, ontvangsturen en de beschikbare ruimte om aan te komen en af te leveren.')],
['camper-veiling-transport','veilingtransport-voertuigen','veilingtransport-documenten','laden-lossen-veiling'])

P('oldtimer-veiling-transport','Voertuigen','Oldtimer van een veiling laten transporteren',
'Oldtimer of klassieker op een veiling gekocht? Bereid afhaling voor met bodemvrijheid, wielbeweging, lekkages, losse onderdelen en overdrachtsafspraken.',
'Bij een oldtimer speelt meer dan alleen leeftijd. Een rijdende klassieker, stilstaand restauratieproject en auto met losse onderdelen vragen elk een andere voorbereiding. ACR beoordeelt uw transportvraag op de actuele staat en de manier waarop de wagen bij de verkoper kan worden overgedragen.',[
('Beschrijf de auto als transportobject','Meld lage delen, uitstekende bumpers, kwetsbare accessoires en de bodemvrijheid. Vermeld wijzigingen aan ophanging of wielen. Bij een restauratieproject is het belangrijk te weten welke delen gemonteerd zijn en welke ontbreken. Foto’s van voor-, achter- en zijkant helpen om de situatie te begrijpen; presenteer bekende gebreken ook als ze niet in de advertentie stonden.'),
('Stilstand kan de laadbaarheid veranderen','Een auto die lange tijd niet reed, kan vaststaande remmen of bandenproblemen hebben. Vraag wat recent daadwerkelijk is gecontroleerd en geef rollen, sturen en remmen afzonderlijk door. Start de motor niet alleen voor het transport wanneer de technische staat onbekend is. Laat onzekerheden beoordelen voordat een gewone rijdende afhaling wordt afgesproken.'),
('Maak een onderdelen- en documentenlijst','Een oldtimerkavel kan extra motoronderdelen, bekleding, wielen of dozen bevatten. Zet ze afzonderlijk op de aanvraag en beschrijf verpakking en aantallen. Geef aan wat bij de auto blijft en wat los wordt overgedragen. Zo worden laadruimte en controle bij aflevering afgestemd op de hele aankoop in plaats van alleen de carrosserie.'),
('Bespreek gewenste bescherming concreet','Heeft u specifieke wensen voor bescherming of vervoer, vermeld die dan vóór de offerte. Deze pagina belooft geen gesloten voertuig, bijzondere verzekering of vaste uitrusting zonder bevestiging. Laat de afgesproken transportwijze en werkzaamheden duidelijk omschrijven. Geef de bestemming en de mogelijkheden om de klassieker daar aan te nemen meteen mee.')],
['Recente beelden en aanwezige kwetsbare delen','Bodemvrijheid en eventuele technische aanpassingen','Vrij rollen, sturen en remmen na stilstand','Losse onderdelen met aantallen en verpakking','Gewenste bescherming en geïnformeerde ontvanger'],
[('Kan een restauratieproject worden vervoerd?','Dat kan worden beoordeeld. Beschrijf ontbrekende of losse delen, wielbeweging, massa en de plek waar het project staat.'),('Is gesloten transport automatisch inbegrepen?','Nee. Wensen voor de transportwijze moeten vooraf worden besproken en uitdrukkelijk worden bevestigd in de concrete opdracht.')],
['niet-rijdende-veilingauto','veilingtransport-documenten','veilingtransport-kosten','meerdere-kavels-ophalen'])

P('pallet-veiling-transport','Goederen','Pallets van een veiling laten ophalen',
'Veilingpallet laten vervoeren? Geef palletmaten, hoogte, gewicht, stapelbaarheid, verpakking en laad- en loshulp door aan ACR voor een offerte.',
'Eén veilingkavel kan meerdere pallets omvatten. Ook een als “pallet” aangeboden partij kan buiten de pallet uitsteken of nog niet transportklaar zijn. Voor een transportbeoordeling zijn daarom de volledige buitenmaten, het gewicht en de afhaalsituatie nodig.',[
('Tel de werkelijke palletplaatsen','Vermeld per pallet lengte, breedte en totale hoogte. Neem overstekende dozen, buizen of machineonderdelen mee in de afmetingen. Geef het aantal pallets en het gewicht per eenheid door in plaats van alleen een gezamenlijk totaal. Dat helpt om de laadruimte en handling te beoordelen zonder aannames over standaardmaten.'),
('Verpakking moet passen bij wat erop staat','Geef aan of de lading stabiel op de pallet staat en welke bescherming aanwezig is. Een folieomwikkeling zegt op zichzelf niet dat kwetsbare of zware goederen geschikt zijn voor vervoer. Meld losse artikelen, breekbare inhoud en een beschadigde pallet. Wie voorbereiding of herverpakking uitvoert, moet vóór de afhaaldag vaststaan.'),
('Stapelbaarheid is een afzonderlijk gegeven','Een pallet met een vlakke bovenkant is niet automatisch stapelbaar. Vermeld wat de verkoper daarover bevestigt en of er kwetsbare delen uitsteken. Geef bijzondere eisen, zoals rechtop houden of beschermen tegen weersinvloeden, vooraf door. ACR bevestigt welke uitvoering mogelijk is; bijzondere behandeling wordt niet verondersteld.'),
('Laden en lossen vragen elk hun eigen hulpmiddel','Noteer of de pallets vanaf de zijkant of via een laadperron bereikbaar zijn en welke hulp beschikbaar is. Controleer ook de bestemming: een harde vlakke ondergrond, beschikbare loshulp en een bereikbare ontvanger moeten passen bij de gekozen uitvoering. Een heftruck op de afhaallocatie betekent niet dat aflevering overal zonder hulpmiddelen kan.')],
['Aantal pallets en maten per pallet','Massa per pallet en eventuele overstek','Verpakking, stabiliteit en pallettoestand','Wel of niet stapelbaar, bevestigd door verkoper','Laadperron, hulpmiddelen en losplaats'],
[('Kan ik een pallet zonder gekend gewicht aanvragen?','U kunt de beschikbare gegevens bezorgen, maar onzeker gewicht moet vóór de definitieve uitvoering worden opgehelderd. Alleen het formaat geeft geen betrouwbare massa.'),('Wordt er automatisch met een laadklep geleverd?','Nee. Geef de laad- en losmogelijkheden door; het passende materieel en inbegrepen werkzaamheden worden per opdracht bevestigd.')],
['veilingtransport-goederen','laden-lossen-veiling','meerdere-kavels-ophalen','veilingtransport-kosten'])

P('machine-veiling-transport','Goederen','Machine uit een veiling laten vervoeren',
'Machine op een veiling gekocht? ACR beoordeelt transport na controle van typeplaat, massa, buitenmaten, demontage, toegang en laad- en losmogelijkheden.',
'Een machine die nog op haar werkplek staat, is niet automatisch klaar voor transport. Loskoppelen, demonteren, verplaatsen en laden zijn verschillende werkzaamheden. Met een duidelijke beschrijving van die stappen kan ACR beoordelen welk vervoer voor uw aankoop haalbaar is.',[
('Begin bij de typeplaat en buitenmaten','Stuur een leesbare foto van de typeplaat en een overzicht van de volledige machine. Geef de beschikbare massa-informatie en totale transportmaten door. Vermeld uitstekende tafels, armen, toevoerrollen en losse onderdelen. Wordt een deel verwijderd vóór afhaling, laat dan bevestigen wat de maten en massa na die voorbereiding zullen zijn.'),
('Maak duidelijk wie de machine gereedmaakt','Vraag of de machine al losgekoppeld en vrijstaand is. Elektrische aansluitingen, leidingen, verankeringen en technische demontage moeten door een geschikte partij worden behandeld. ACR rekent die taken niet zonder afspraak tot een transport. Voor complexe installaties kan een gespecialiseerd demontage- of hijsbedrijf nodig zijn voordat de laadrit uitvoerbaar wordt.'),
('Beschrijf het traject door het gebouw','De smalste deur, laagste doorgang, drempels en beschikbare draaicirkel kunnen de verplaatsing beperken. Stuur foto’s van het hele traject tot aan de laadplaats. Vermeld welke apparatuur beschikbaar is en wie deze bedient. Een machine die eerder door een grote opening is binnengebracht, kan niet vanzelf langs elke huidige deur weer naar buiten.'),
('Bevestig ook waar en hoe zij wordt afgeleverd','De ontvangende partij moet voldoende toegang en geschikte losmiddelen hebben. Geef aan of de machine buiten wordt aangenomen of op een specifieke plek moet komen. Binnenplaatsen, positioneren en installeren zijn geen standaardonderdeel van vervoer. Maak per stap duidelijk wie verantwoordelijk is en wat in de bevestigde opdracht is opgenomen.')],
['Typeplaat, model en beschikbare massa','Volledige transportmaten en losse delen','Status van ontkoppeling en demontage','Deuren, doorgangen en traject naar het laadpunt','Geschikte laad- en losmiddelen met bediener'],
[('Is demontage inbegrepen bij machinetransport?','Alleen wanneer dit afzonderlijk is overeengekomen. Geef de huidige situatie en benodigde werkzaamheden vooraf door; specialistisch werk kan een andere uitvoerder vragen.'),('Kan een machine meteen op haar werkplek worden gezet?','Dat moet apart worden beoordeeld. Aflevering, intern verplaatsen en installatie zijn verschillende werkzaamheden en moeten duidelijk in de afspraken staan.')],
['heftruck-veiling-transport','minigraver-veiling-transport','laden-lossen-veiling','veilingtransport-goederen'])

P('heftruck-veiling-transport','Goederen','Heftruck van een veiling laten ophalen',
'Veilingheftruck vervoeren? Geef massa, masthoogte, vorken, aandrijving en rijdbaarheid door. ACR beoordeelt de uitvoering en bereikbaarheid vooraf.',
'Een heftruck kan compact ogen en toch een aanzienlijke massa hebben. Een hoge mast, losse vorken of een lege tractiebatterij kunnen de laadopdracht veranderen. ACR beoordeelt de afhaling met de werkelijke gegevens, niet op basis van de indruk die één foto geeft.',[
('Zoek de juiste gegevens op de typeplaat','Bezorg merk, model en de beschikbare massa-informatie van de complete heftruck. Verwar hefvermogen niet met eigen gewicht: die gegevens beantwoorden verschillende vragen. Vermeld de hoogte in transportstand, de breedte en de lengte met vorken of ander aanbouwdeel. Als de batterij of een contragewicht ontbreekt, moet dat expliciet op de aanvraag staan.'),
('Controleer aandrijving en besturing','Vraag of de heftruck daadwerkelijk kan rijden, sturen en remmen en of een geschikte bediener aanwezig is. Bij een elektrische uitvoering zijn de toestand van de batterij en inschakelbaarheid relevant. Een defecte of lege machine kan een andere laadwijze nodig maken. Laat niet aannemen dat een beschikbare sleutel betekent dat zij ook verplaatsbaar is.'),
('Meld mast en aanbouwdelen afzonderlijk','Beschrijf vorken, verlenglepels, sideshift of ander uitrustingsmateriaal. Geef door welke delen gemonteerd blijven en welke los worden aangeboden. Voor verwijderen of verplaatsen van onderdelen zijn aparte afspraken nodig. Een machine lager maken voor vervoer mag niet worden ingepland alsof dat automatisch bij de gewone afhaling hoort.'),
('Voorzie een passende laad- en losplek','Ondergrond, hellingen, poorthoogte en manoeuvreerruimte spelen op beide adressen mee. Geef ook aan hoe de heftruck vanaf de standplaats naar de laadplaats komt. De ontvanger moet weten of de machine operationeel is. Vervoer wordt pas bevestigd wanneer de gegevens en beschikbare middelen bij de uitvoering passen.')],
['Eigen massa, niet alleen hefvermogen','Hoogte in transportstand en totale buitenmaten','Mast, vorken en losse aanbouwdelen','Rijden, sturen, remmen en batterijtoestand','Ondergrond, toegang en bediener op beide locaties'],
[('Is het hefvermogen hetzelfde als het transportgewicht?','Nee. Voor de transportbeoordeling zijn gegevens over de massa van de machine zelf nodig, inclusief de uitrusting waarin zij wordt vervoerd.'),('Kan een elektrische heftruck met lege batterij mee?','Dat vraagt een aparte laadbeoordeling. Meld de toestand en verplaatsbaarheid vooraf; een gewoon rijdend transport wordt niet automatisch aangenomen.')],
['machine-veiling-transport','laden-lossen-veiling','veilingtransport-kosten','veilingtransport-checklist'])

P('minigraver-veiling-transport','Goederen','Minigraver van een veiling laten vervoeren',
'Minigraver gekocht op een veiling? Bezorg massa, transportmaten, rupstoestand, aanbouwdelen en bereikbaarheid voor een beoordeling van het transport.',
'Een minigraver moet met de juiste transportmaten en alle aanbouwdelen worden aangemeld. De naam “mini” zegt weinig over de massa of de benodigde ruimte. ACR bekijkt of de lading, toegang en planning passen bij een concrete transportuitvoering.',[
('Gebruik de maten in transportstand','Geef lengte, breedte en hoogte op zoals de machine vervoerd zal worden. Vermeld een verstelbaar onderstel, cabine of beugel en de positie van arm en bak. Bezorg de beschikbare massa-informatie en een typeplaatfoto. Als onderdelen vóór transport worden verwijderd, moet duidelijk zijn wie dat uitvoert en welke eenheden daarna moeten worden geladen.'),
('Maak een lijst van bakken en andere aanbouwdelen','Een extra bak, breekhamer, grijper of snelwissel kan apart ruimte en gewicht vragen. Geef per onderdeel aantallen, maten en massa door voor zover bekend. Beschrijf wat aan de machine blijft en wat los wordt aangeboden. Zo wordt een veilingkavel met meerdere onderdelen niet onbedoeld als alleen één rijdende minigraver ingepland.'),
('Controleer verplaatsbaarheid en ondergrond','Meld of de machine start, rijdt en bestuurbaar is en of de rupsen in bruikbare toestand zijn. Geef lekkages en bekende defecten door. Beschrijf de standplaats en het traject tot het laadpunt: zachte grond, een smalle poort of een helling kan de afhaling veranderen. Een geschikte bediener en vrije toegang moeten op het afgesproken moment aanwezig zijn.'),
('Leg de loslocatie vooraf vast','Vertel of de bestemming een werf, bedrijfsterrein of particulier adres is. De ondergrond en beschikbare ruimte moeten passen bij aankomst en lossen. Een verplaatsing verder over het terrein of door een smalle doorgang is geen vanzelfsprekend onderdeel van de rit. Laat de werkelijke uitvoering bevestigen voordat u verdere werkzaamheden op de levering afstemt.')],
['Massa en maten in transportstand','Cabine, beugel, rupsen en verstelbaar onderstel','Lijst van bakken en andere aanbouwdelen','Rijdbaarheid, lekkages en bereikbare bediener','Vrije laad- en losplek met geschikte ondergrond'],
[('Kunnen extra bakken mee?','Dat kan worden beoordeeld wanneer u alle aantallen en gegevens doorgeeft. Extra aanbouwdelen zijn afzonderlijke lading en moeten in ruimte en massa worden meegenomen.'),('Kan een defecte minigraver worden opgehaald?','Meld het defect, de wiel- of rupsbeweging en beschikbare ondersteuning. De laadwijze wordt afzonderlijk bepaald; niet elke defecte machine kan als gewone rijdende lading worden aangenomen.')],
['machine-veiling-transport','landbouwmachine-veiling-transport','laden-lossen-veiling','veilingtransport-kosten'])

P('landbouwmachine-veiling-transport','Goederen','Landbouwmachine uit een veiling transporteren',
'Tractor, werktuig of landbouwmachine op een veiling gekocht? Geef maten, massa, uitstekende delen, technische staat en erfbereikbaarheid door aan ACR.',
'Een landbouwkavel kan een zelfstandig rijdende machine zijn, maar ook een werktuig, aanhanger of combinatie van losse delen. Voor transport moet de hele aankoop in kaart worden gebracht. ACR beoordeelt de aanvraag op de concrete maten en uitvoering; speciale of grote lading wordt niet zonder controle geaccepteerd.',[
('Beschrijf het werktuig in de aangeboden toestand','Geef de grootste breedte, hoogte en lengte door, inclusief uitstekende tanden, banden, assen of armen. Vermeld of delen kunnen worden ingeklapt en wie dat vóór afhaling uitvoert. Bezorg beschikbare massa-informatie en duidelijke foto’s. Maak onderscheid tussen de werkstand en de bevestigde transportstand van de machine.'),
('Vergeet losse onderdelen niet','Een aftakas, frontgewicht, extra wielset of los aanbouwdeel kan bij het kavel horen. Zet alles op een genummerde lijst en geef aan hoe het ter plaatse klaarstaat. Losse of scherpe onderdelen moeten geschikt zijn voor de afgesproken handling en verpakking. Het verplaatsen van zware delen op het erf vraagt beschikbare middelen en een geschikte bediener.'),
('Controleer de toegang tot het erf','Vraag of het laadpunt over een verharde en vrije route bereikbaar is. Vermeld modder, hoogtebeperkingen, smalle poorten en scherpe bochten. Geef bij een rijdende machine aan of zij start, stuurt en remt. Een tractor of werktuig achteraan een loods moet eerst op een plek kunnen komen waar de afgesproken laadwijze mogelijk is.'),
('Bespreek bijzondere transportvragen vooraf','Een uitzonderlijke breedte, hoge massa of ingewikkelde voorbereiding kan een gespecialiseerde oplossing vereisen. Deze pagina belooft geen uitzonderlijk vervoer of specifieke vergunningen. ACR beoordeelt eerst wat voor uw kavel haalbaar is. Geef de uiteindelijke bestemming meteen door, inclusief de middelen om de machine of het werktuig daar aan te nemen.')],
['Soort machine of werktuig met duidelijke foto’s','Grootste maten in bevestigde transportstand','Massa en alle losse aanbouwdelen','Verharding, poorten en route tot het laadpunt','Technische toestand en beschikbare laad- en losmiddelen'],
[('Kan elk landbouwwerktuig worden vervoerd?','Nee, dat wordt per aanvraag beoordeeld. Grote maten, massa of specialistisch laadwerk kunnen een andere oplossing of uitvoerder noodzakelijk maken.'),('Moet de machine vooraf ingeklapt zijn?','De transportstand moet bekend en uitvoerbaar zijn. Spreek af wie de voorbereiding doet; ombouwen of inklappen is niet automatisch onderdeel van de transportopdracht.')],
['machine-veiling-transport','minigraver-veiling-transport','veilingtransport-goederen','veilingtransport-checklist'])

P('garage-inventaris-veiling-transport','Goederen','Garage-inventaris van een veiling laten ophalen',
'Garagegereedschap, werkbanken, kasten of werkplaatsinventaris gekocht? Maak met ACR een laadlijst en stem demontage, verpakking en transport af.',
'Een garage-inventaris bestaat vaak uit een mix van verrijdbaar gereedschap, zware kasten en apparatuur die nog vast aangesloten is. Eén kavelnummer kan daardoor een omvangrijke laadlijst verbergen. ACR kan het transport beoordelen wanneer duidelijk is welke eenheden gereedstaan en welke voorbereiding nog nodig is.',[
('Verdeel de inventaris in herkenbare eenheden','Maak een lijst van kasten, werkbanken, machines, dozen en losse gereedschappen. Geef per eenheid maten, massa en verplaatsbaarheid aan. Noteer of laden en deuren zijn gesloten en of onderdelen apart worden aangeboden. Een overzicht per kavel maakt het mogelijk om bij afhaling en levering aantallen te vergelijken.'),
('Vast opgestelde apparatuur vraagt voorbereiding','Een hefbrug, compressorinstallatie of vaste machine kan niet worden behandeld als een los meubel. Meld aansluitingen, verankeringen en de benodigde demontage. Laat geschikte personen bevestigen wat vóór de rit veilig wordt losgemaakt en hoe de delen daarna worden aangeboden. Technisch loskoppelen en demonteren zijn alleen inbegrepen wanneer dat uitdrukkelijk is afgesproken.'),
('Beschrijf gewicht en inhoud van gereedschapskasten','Een kast gevuld met gereedschap verschilt sterk van een lege kast met dezelfde buitenmaten. Geef aan of inhoud op haar plaats blijft of apart wordt verpakt. Meld olie, vloeistoffen, gasflessen of andere bijzondere inhoud vooraf voor beoordeling. Veronderstel niet dat alles wat in een werkplaats staat in één gewone inventarisrit kan worden meegenomen.'),
('Plan de overdracht op de nieuwe werkplaats','Controleer deuren, drempels, ontvangsttijd en hulpmiddelen op de bestemming. Spreek af waar de eenheden worden neergezet en wie de aantallen aftekent. Installatie, vullen, aansluiten en het bedrijfsklaar maken van apparatuur zijn andere werkzaamheden dan het afleveren. Geef zulke wensen apart op zodat ze niet pas tijdens lossen naar voren komen.')],
['Genummerde lijst met kasten, apparatuur en dozen','Maten en massa inclusief aanwezige inhoud','Vast opgestelde of nog aangesloten apparatuur','Losmaakwerk, verpakking en verplaatsmiddelen','Bijzondere inhoud en afgesproken losplek'],
[('Kan een hefbrug mee met garage-inventaris?','Dat vraagt afzonderlijke beoordeling van demontage, delen, massa en laadwijze. Een gemonteerde hefbrug wordt niet zonder voorbereiding als los stuk inventaris beschouwd.'),('Worden gereedschapskasten met inhoud vervoerd?','Beschrijf de inhoud en hoe die wordt voorbereid. ACR bevestigt de haalbare uitvoering; laden en deuren moeten geschikt zijn voor de afgesproken handling.')],
['machine-veiling-transport','pallet-veiling-transport','meerdere-kavels-ophalen','laden-lossen-veiling'])

P('horeca-inventaris-veiling-transport','Goederen','Horeca-inventaris van een veiling transporteren',
'Horeca-apparatuur, tafels, kasten of keukeninventaris laten ophalen? Geef aantallen, maten, aansluitingen, verpakking en toegang door voor transport.',
'Bij horeca-inventaris komen losse meubels en vast aangesloten apparatuur vaak in hetzelfde kavel voor. Een werkbare transportaanvraag beschrijft daarom wat los en bereikbaar klaarstaat. ACR beoordeelt het vervoer met de werkelijke eenheden en de situatie op de afhaal- en afleverlocatie.',[
('Tel meubels en apparatuur afzonderlijk','Noteer per soort de aantallen: bijvoorbeeld tafels, stoelen, losse kasten en keukenapparaten. Geef maten en beschikbare massa-informatie mee. Vermeld glas, losse rekken, werkbladen en andere kwetsbare delen. Een omschrijving als “volledige keuken” is te breed om laadruimte en handelingen goed op af te stemmen.'),
('Laat aansluitingen en installaties eerst beoordelen','Gas-, water- en elektrische aansluitingen en vaste afvoerleidingen vragen passende voorbereiding door een geschikte partij. Beschrijf wat nog aangesloten is en wie het losmaakt. Ook het verplaatsen van zware toestellen uit een keuken is een aparte stap. Ontkoppeling, installatie en specialistische behandeling zijn niet stilzwijgend inbegrepen bij een rit.'),
('Controleer de route door het gebouw','Een restaurant in een stadscentrum kan trappen, nauwe gangen of een beperkte laadzone hebben. Bezorg foto’s van deuren en het traject naar buiten. Vraag of een goederenlift beschikbaar is en of de maten en capaciteit passen bij de aankoop. Meld toegangsuren en praktische beperkingen vóór de transportbevestiging.'),
('Stem bescherming en ontvangst af','Vertel hoe apparaten, glas en losse onderdelen verpakt zijn en welke behandeling de verkoper aangeeft. Bespreek bijzondere wensen zoals rechtop houden vooraf. Zorg dat de bestemming genoeg ruimte en geschikte loshulp heeft. Aflevering van apparatuur houdt geen technische ingebruikstelling in; controleer met uw installateur wat na transport nodig is.')],
['Aantallen per meubel of apparaat','Buitenmaten, massa en losse rekken of glasdelen','Status van gas, water en elektrische aansluitingen','Deuren, trappen, laadzone en eventuele lift','Bescherming, loshulp en ontvangstvenster'],
[('Worden koeltoestellen zomaar als losse meubels meegenomen?','Nee. Meld type, toestand, maten, aansluitingen en eventuele bijzondere instructies. De voorbereiding en transportwijze moeten bij het concrete apparaat passen.'),('Is demonteren van de keuken inbegrepen?','Alleen wanneer dit apart is bevestigd. Vermeld welk werk nog nodig is en welke partij dit vóór de laadrit uitvoert.')],
['veilingtransport-goederen','machine-veiling-transport','laden-lossen-veiling','veilingtransport-kosten'])

P('kantoorinventaris-veiling-transport','Goederen','Kantoorinventaris uit een veiling laten vervoeren',
'Bureaus, stoelen, kasten en kantoorapparatuur op een veiling gekocht? ACR beoordeelt ophalen en leveren met aantallen, maten, verdieping en verpakking.',
'Kantoorinventaris lijkt vaak eenvoudig te verplaatsen, maar volume, verdiepingen en losse onderdelen kunnen de rit sterk beïnvloeden. ACR bekijkt het transport met een concrete inventarislijst en informatie over de route door beide gebouwen. Zo wordt duidelijk wat voor de laadrit voorbereid moet zijn.',[
('Bereken de ruimte aan de hand van een inventarislijst','Geef aantallen, buitenmaten en de aangeboden toestand van bureaus, stoelen en kasten. Vermeld of meubels gemonteerd blijven of al in delen klaarstaan. Losse bureaubladen, ladeblokken en kabelgoten horen ieder op de lijst. Een aantal werkplekken is geen eenduidige maat voor de transporteenheden die werkelijk moeten worden meegenomen.'),
('Verdieping en loopafstand maken verschil','Beschrijf het traject van kantoor tot voertuig, inclusief lift, trap, drempels en deuren. Vermeld liftmaten en de beschikbare capaciteit voor zover bekend. Ook de afstand van ingang tot laadzone telt mee. Vraag welke toegang en welk laadvenster op de afhaaldag zijn toegestaan; alleen het straatadres is voor zo’n beoordeling niet genoeg.'),
('Maak kwetsbare apparatuur herkenbaar','Computerschermen, printers en andere apparatuur moeten apart worden opgegeven met hun verpakking. Laat de verkoper aangeven wat bij het kavel hoort en hoe het gereedstaat. Dataverwijdering, technische controle en het gebruiksklaar maken van apparatuur zijn geen onderdeel van een gewone transportaanvraag. Stuur ook geen onnodige account- of personeelsgegevens mee in de laadlijst.'),
('Plan de aflevervolgorde en ontvangst','Geeft u voor meerdere verdiepingen of kamers een bestemming op, maak dan duidelijk wat de gevraagde aflevering inhoudt. Binnenplaatsen of montage wordt apart beoordeeld. Spreek af wie de inventaris ontvangt en wie controleert of losse delen compleet zijn. De ontvangende locatie moet beschikken over ruimte en ondersteuning die passen bij de afgesproken uitvoering.')],
['Aantallen en maten van meubels per soort','Gemonteerd of gedemonteerd aangeboden','Verdieping, liftmaten, trap en loopafstand','Verpakking van schermen en andere apparatuur','Afleverlocatie, ontvanger en gewenste plaatsing'],
[('Kan een volledige kantoorverdieping worden aangevraagd?','Ja, met een inventarislijst en toegangsgegevens. De omvang, beschikbare ondersteuning en timing worden eerst beoordeeld; een foto van de ruimte is geen volledige laadlijst.'),('Zetten jullie meubels na transport in elkaar?','Montage is alleen inbegrepen als die afzonderlijk is afgesproken. Geef vooraf aan of meubels in delen worden aangeboden en wat u op de bestemming verwacht.')],
['meerdere-kavels-ophalen','pallet-veiling-transport','laden-lossen-veiling','veilingtransport-checklist'])

P('meerdere-kavels-ophalen','Voorbereiding','Meerdere veilingkavels samen laten ophalen',
'Verschillende kavels combineren in één transportaanvraag? Maak per locatie een laadlijst met tijdsloten, afmetingen, massa en vrijgavegegevens.',
'Meerdere aankopen combineren kan praktisch zijn, maar alleen wanneer route, laadruimte en afhaalvensters samen passen. ACR beoordeelt de volledige lijst als één transportvraag. Het aantal kavelnummers alleen zegt weinig over de ruimte of het aantal stops dat nodig is.',[
('Groepeer eerst op afhaallocatie','Maak per werkelijk laadadres een lijst van kavels en de bijbehorende transporteenheden. Geef aan welke aankopen door dezelfde contactpersoon worden vrijgegeven. Verwar een gedeelde veilingnaam niet met een gezamenlijke locatie. Een platform kan kavels op verschillende terreinen aanbieden en de afhaalafspraken kunnen per kavel verschillen.'),
('Zet alle tijdvensters naast elkaar','Noteer per adres de datum, begin- en eindtijd en eventuele reservering. Een combinatie die qua kilometers logisch lijkt, kan toch niet passen wanneer de tijdsloten overlappen. Geef ook aan welke volgorde door de laad- of losplaats wordt opgelegd. Laat ACR de haalbare planning bevestigen voordat u van één gezamenlijke rit uitgaat.'),
('Maak het totale volume zichtbaar','Vermeld maten en massa per voertuig, pallet of los onderdeel. Noteer welke goederen stapelbaar zijn en welke niet. Een auto plus een partij gereedschap vraagt een andere beoordeling dan twee gewone laadstops. Ook de ruimte om goederen bereikbaar en geschikt te plaatsen moet passen bij de complete lading.'),
('Controleer levering en documenten per onderdeel','Geef aan of alles naar één adres gaat of dat meerdere ontvangers betrokken zijn. Houd vrijgavegegevens en aantallen per kavel uit elkaar. Spreek vooraf af hoe wijzigingen worden behandeld wanneer één aankoop niet gereed of niet vrijgegeven is. Zo is duidelijk of het resterende deel van de opdracht nog volgens afspraak kan doorgaan.')],
['Per locatie: kavels en fysieke transporteenheden','Afhaaldag en tijdvak per stop','Massa, maten, verpakking en stapelbaarheid','Vrijgave en contactpersoon per locatie','Bestemming en ontvanger per onderdeel'],
[('Kunnen kavels van verschillende veilingen samen?','Dat kan worden bekeken. De afhaaldagen, route en lading moeten samen passen; de combinatie is pas definitief na bevestiging.'),('Levert samen ophalen altijd een voordeel op?','Dat kan niet worden beloofd. Extra stops, tijdsdruk of onhandige laadvolgorde kunnen de uitvoering veranderen. Laat de volledige combinatie beoordelen.')],
['veilingtransport-kosten','afhaaldag-veiling-regelen','veilingtransport-documenten','veilingtransport-goederen'])

P('veilingtransport-belgie','Routes','Veilingtransport binnen België regelen',
'Veilingaankoop in België laten ophalen en leveren? ACR beoordeelt de route, voertuig- of goederengegevens, afhaaltijd en bereikbaarheid op beide locaties.',
'Een binnenlandse veilingrit kan een korte verplaatsing naar een garage zijn of een transport tussen twee provincies. Het concrete adres, afhaalvenster en de lading bepalen de uitvoering. Bezorg ACR daarom de hele opdracht, ook wanneer u alleen “ergens in België” in de veilingomschrijving ziet staan.',[
('Vraag het werkelijke afhaaladres op','De plaatsnaam van de veiling of de vestiging van het platform hoeft niet het laadadres van uw kavel te zijn. Gebruik het adres uit uw afhaalgegevens en geef de juiste toegang of poort mee. Meld of de contactpersoon ter plaatse een andere partij is dan degene die de aankoop heeft gefactureerd.'),
('Beschrijf beide zijden van de route','Een ruim terrein aan de laadzijde helpt niet wanneer de ontvanger in een krappe straat zonder losmogelijkheid zit. Noteer parkeerruimte, poorten, hoogtebeperkingen en toegangstijden op beide adressen. Bij een bedrijfsontvanger moeten de opgegeven openingsuren ook werkelijk gelden voor het aannemen van uw voertuig of goederen.'),
('Laat de lading de transportkeuze bepalen','Stuur voor voertuigen rijdbaarheid en voertuiggegevens; voor goederen de aantallen, maten en massa. Vermeld ontbrekende sleutels, losse onderdelen of vereiste voorbereiding. Een korte afstand maakt een ingewikkelde laadopdracht niet automatisch eenvoudig. De bevestigde uitvoering moet bij het kavel passen, ook op een lokale route.'),
('Stem een haalbaar afhaal- en levermoment af','De afhaaldag is vaak al bepaald voordat de rit wordt aangevraagd. Geef het tijdvak meteen door en meld een strikte ontvangstdag op de bestemming. ACR bespreekt beschikbare planning en prijs met u. Een aanvraag betekent niet dat elk moment of elke combinatie van tijdsvoorwaarden direct kan worden bevestigd.')],
['Volledig laadadres met juiste terrein- of poortinformatie','Losadres en beschikbare manoeuvreerruimte','Kavelgegevens, maten, massa en toestand','Afhaalvenster én ontvangsturen','Contactpersoon aan beide zijden'],
[('Kan een Belgische veilingauto rechtstreeks naar mijn garage?','Dat kan worden aangevraagd. De garage moet de auto op het afgesproken moment kunnen aannemen en over een geschikte losplek beschikken.'),('Kan ik vanuit elke provincie aanvragen?','Geef uw exacte route door. ACR beoordeelt de haalbaarheid en planning per aanvraag; deze pagina belooft geen lokale vestiging in elke provincie.')],
['veilingtransport-nederland-belgie','veilingtransport-kosten','veiling-auto-ophalen','veilingtransport-checklist'])

P('veilingtransport-nederland-belgie','Routes','Veilingtransport van Nederland naar België',
'Kavel in Nederland gekocht en in België laten leveren? Vraag transport bij ACR aan met echte adressen, afhaalvenster, vrijgave en volledige laadgegevens.',
'Een Nederlandse veilingaankoop naar België laten brengen begint met het juiste laadadres en de ontvangst op de Belgische bestemming. ACR bespreekt de concrete route en lading met u. Zowel een voertuig als een partij goederen vraagt volledige afhaalgegevens voordat een rit kan worden bevestigd.',[
('Controleer waar het kavel werkelijk staat','Een Nederlandse platformnaam of factuuradres is geen zekerheid over het terrein waar uw aankoop klaarstaat. Gebruik de afhaalinformatie van het kavel. Noteer de ingang, contactpersoon en eventuele afspraak. Vraag ook of de afhaler vooraf moet worden aangemeld en welke gegevens de locatie daarvoor vraagt.'),
('Laat de afhaaldag de routeplanning sturen','Geef een vast tijdslot of beperkt afhaalvenster meteen door. Combineert u verschillende Nederlandse locaties, vermeld alle tijden afzonderlijk. Een gezamenlijke rit kan alleen worden bevestigd als die afspraken elkaar niet uitsluiten. Meld wijzigingen direct; een aanpassing van het platform wordt niet automatisch aan ACR doorgestuurd.'),
('Maak toestand en laadwijze grensoverschrijdend duidelijk','Voor een auto meldt u rollen, sturen, remmen en sleutels. Voor goederen zijn transportmaten, massa, verpakking en laadondersteuning nodig. Geef informatie die een afhaler ter plaatse kan gebruiken, inclusief een bereikbaar telefoonnummer. Een kavelnummer zonder duidelijke omschrijving laat teveel vragen open als verkoper en koper niet samen aanwezig zijn.'),
('Levering in België hoort vanaf het begin in de aanvraag','Vermeld de uiteindelijke bestemming en de beschikbare loshulp. Gaat een auto naar een garage, laat de ontvangst bevestigen. Voor machines moet ook de toegankelijkheid van het Belgische gebouw bekend zijn. Vragen over registratie, keuring, aankoopbelasting of andere administratieve stappen vallen buiten een gewone transportofferte en moeten afzonderlijk worden nagegaan.')],
['Nederlands laadadres uit de afhaalinformatie','Belgisch losadres met ontvangsturen','Tijdslot, aanmelding en vrijgavegegevens','Maten, massa, toestand en beschikbare laadhulp','Bereikbare locatiecontacten aan beide zijden'],
[('Kan een niet-rijdende auto uit Nederland worden opgehaald?','Dat kan worden beoordeeld. Geef de beperkingen, sleutels en bereikbaarheid door zodat de laadwijze vooraf kan worden afgestemd.'),('Is Belgische inschrijving inbegrepen?','Deze aanvraag gaat over vervoer. Inschrijving, keuring en aankoopadministratie zijn geen automatisch inbegrepen onderdeel van de transportopdracht.')],
['troostwijk-transport','veilingtransport-duitsland-belgie','veilingtransport-documenten','niet-rijdende-veilingauto'])

P('veilingtransport-duitsland-belgie','Routes','Veilingaankoop uit Duitsland naar België vervoeren',
'Voertuig of goederen in Duitsland geveild? ACR beoordeelt vervoer naar België met afhaalgegevens, technische toestand, laadmogelijkheden en ontvangst.',
'Bij een aankoop in Duitsland is het belangrijk dat laadplaats, vrijgave en contactgegevens vooraf ondubbelzinnig zijn. ACR bekijkt uw route naar België op basis van de werkelijke lading en beschikbare planning. Bezorg de oorspronkelijke kavelinformatie samen met uw eigen duidelijke laadlijst.',[
('Gebruik het adres van de daadwerkelijke standplaats','Vraag de juiste poort, terreinreferentie en contactpersoon voor de afhaling op. Grote vestigingen kunnen een afzonderlijke laadzone hebben. Vermeld openingstijden en eventuele verplichte aanmelding. Het adres van een hoofdkantoor of facturatieafdeling is niet voldoende als de aankoop elders wordt overgedragen.'),
('Leg technische gegevens begrijpelijk vast','Stuur het merk en type van voertuig of machine en de beschikbare documentatie mee. Geef maten en massa afzonderlijk op. Bij een voertuig beschrijft u starten, rollen, sturen en remmen zonder alleen op een algemene advertentieterm te vertrouwen. Voor losse goederen zijn aantallen, verpakking en laadondersteuning belangrijker dan de verkoopcategorie.'),
('Controleer dat vrijgave voor de afhaler klaarstaat','Vraag welke gegevens de laadlocatie nodig heeft om uw aankoop mee te geven. Stem een eventueel afhaalcontact of referentienummer vooraf af. Stuur geen volledige accounttoegang door waar een afhaaldocument volstaat. Meld ontbrekende documenten of onzekerheden voordat de rit wordt bevestigd; transport kan de vrijgavevoorwaarden van de verkoper niet vervangen.'),
('Koppel het Duitse laadvenster aan Belgische ontvangst','Geef tijdsbeperkingen op beide locaties meteen door. Een machine kan alleen volgens afspraak worden geleverd wanneer de ontvanger toegang en geschikte losmiddelen heeft. Bespreek de transportuitvoering en planning met ACR. Registratie, aankoopfiscaliteit en technische toelating van een voertuig zijn afzonderlijke onderwerpen die niet door deze transportpagina worden geregeld.')],
['Duitse standplaats, poort en laadcontact','Afhaalvenster en eventuele verplichte aanmelding','Begrijpelijke voertuig- of machinegegevens','Benodigde vrijgave en mee te geven documenten','Belgische ontvangst met passende losmogelijkheden'],
[('Kan de rit naar een Belgische hersteller gaan?','Ja, u kunt dat als bestemming opgeven. Stem ontvangst en losplaats eerst met de hersteller af en deel diens contactgegevens met ACR.'),('Regelt ACR alle aankoopadministratie in Duitsland?','Daar wordt hier geen toezegging over gedaan. Deze aanvraag betreft vervoer; administratieve wensen moeten apart worden besproken en bevestigd.')],
['veilingtransport-nederland-belgie','veilingtransport-documenten','veilingtransport-voertuigen','machine-veiling-transport'])

P('veilingtransport-luxemburg-belgie','Routes','Veilingtransport van Luxemburg naar België',
'Veilingkavel in Luxemburg laten ophalen voor levering in België? ACR bekijkt uw route, afhaaltijd, voertuig of goederen, vrijgave en laad- en loshulp.',
'Een route tussen Luxemburg en België vraagt dezelfde voorbereiding als een andere concrete veilingrit: de juiste lading, twee volledige adressen en haalbare tijdvensters. ACR beoordeelt uw aanvraag persoonlijk. De landsgrens of afstand alleen is geen voldoende basis voor een definitieve prijs.',[
('Maak laadlocatie en contactpersoon herkenbaar','Bezorg het adres waar het kavel werkelijk klaarstaat, met de naam van het terrein of bedrijf en eventuele poortinstructies. Geef een rechtstreeks bereikbaar nummer voor de afhaaldag. Vermeld welke afhaalreferentie nodig is en of de afhaler op voorhand bij de locatie moet zijn aangemeld.'),
('Laat de ontvangende partij direct meedenken','Geef de Belgische eindbestemming in dezelfde aanvraag op. Meld toegangstijden, beperkte ruimte en de beschikbare loshulp. Gaat het om een bedrijf dat slechts op afspraak ontvangt, laat het geschikte venster vóór het vastleggen van de rit bevestigen. Een aflevering zonder bereikbare ontvanger is geen vanzelfsprekende standaardoplossing.'),
('Voertuigen en goederen vragen andere gegevens','Bij een voertuig zijn technische toestand, maten, massa en sleutels nodig. Bij pallets, machines of inventaris beschrijft u de fysieke transporteenheden en hun verpakking. Losse onderdelen moet u apart noemen. Vraag de verkoper om ontbrekende gegevens als de kavelomschrijving geen bruikbare informatie voor de laadplanning bevat.'),
('Bevestig uitvoering op basis van de complete opdracht','Bezorg afhaalvenster, vrijgave en alle bijzondere handelingen aan ACR. Vermeld of verschillende kavels of een extra stop gecombineerd moeten worden. De planning wordt pas definitief na bevestiging. Eventuele vragen over aankoopadministratie of het in gebruik nemen van een voertuig zijn aparte werkzaamheden, naast het overeengekomen vervoer.')],
['Laadadres in Luxemburg met terreinreferentie','Afhaalmoment en bereikbare locatiecontactpersoon','Benodigde vrijgave en kavelnummer','Aantal eenheden met maten, massa en toestand','Bestemming in België met ontvangst en loshulp'],
[('Kan ik een kleine aankoop uit Luxemburg laten beoordelen?','Ja, geef inhoud, route en afhaalvenster door. ACR bekijkt de praktische uitvoering; een kleine koopprijs zegt niet hoeveel transportwerk nodig is.'),('Is een transportaanvraag meteen een reservering?','Nee. ACR bevestigt eerst de haalbare rit, prijs en planning. Zorg dat de afhaalvoorwaarden van het kavel daarbij aansluiten.')],
['veilingtransport-belgie','veilingtransport-duitsland-belgie','veilingtransport-kosten','veilingtransport-checklist'])

P('veilingtransport-frankrijk-belgie','Routes','Veilingtransport van Frankrijk naar België',
'Veilingaankoop in Frankrijk naar België laten vervoeren? Geef ACR de werkelijke standplaats, afhaalafspraak, vrijgave en volledige voertuig- of goederengegevens.',
'Een Franse veilingauto of partij goederen naar België laten brengen vraagt een duidelijke afhaalopdracht. Met alleen de veilingnaam en een gewenste leverdag kan de rit niet worden ingepland. ACR beoordeelt de route met beide adressen, de lading en de tijdsvoorwaarden van verkoper en ontvanger.',[
('Controleer de plaats van afgifte','Vraag waar de aankoop werkelijk staat en welke toegang gebruikt moet worden. Bezorg naam en telefoonnummer van de contactpersoon die het voertuig of de goederen kan vrijgeven. Geef de oorspronkelijke afhaalinformatie mee, zodat referenties en afspraken herkenbaar blijven. Een platformadres of plaatsnaam alleen is geen volledig laadadres.'),
('Vertaal de kavelomschrijving naar een laadopdracht','Beschrijf bij een voertuig de actuele toestand en vermeld sleutels, documenten en losse onderdelen. Bij goederen noteert u aantallen, buitenmaten, massa en verpakking. Houd onbekende gegevens zichtbaar in de aanvraag. Een algemene term voor een defect, beschadigd of ongecontroleerd kavel mag niet als bevestiging van probleemloze laadbaarheid worden gebruikt.'),
('Stem de afspraak aan de laadzijde af','De verkoper kan een vast afhaalvenster of voorafgaande aanmelding vragen. Geef die informatie door voordat u een rit laat bevestigen. Controleer wie geschikte laadhulp levert en welke voorbereiding al moet zijn uitgevoerd. Een transportopdracht verandert de openingstijden of vrijgavevoorwaarden van de Franse locatie niet.'),
('Maak de aflevering in België concreet','Een garage, werkplaats of woning moet klaar zijn om de aankoop aan te nemen. Vermeld een loscontact, manoeuvreerruimte en eventuele hulpmiddelen. ACR bevestigt de uitvoering op basis van de volledige route. Administratieve vragen over aankoop, registratie of inbedrijfstelling vallen buiten deze praktische transportgids en moeten afzonderlijk worden nagegaan.')],
['Frans afhaaladres en terrein- of poortgegevens','Contactpersoon en originele afhaalreferenties','Actuele toestand en maten van de lading','Afhaalvenster en beschikbare ondersteuning','Belgisch losadres met ontvangstafspraak'],
[('Kan een schadeauto uit Frankrijk naar een garage?','Dat kunt u aanvragen. Beschrijf de schade, wielbeweging, lekkages en de situatie op beide locaties. De transportwijze wordt vóór bevestiging beoordeeld.'),('Zijn documenten voor de aankoop automatisch geregeld?','Nee. Bezorg de vereiste afhaal- en aankoopgegevens zelf en bespreek afzonderlijke administratieve wensen vooraf.')],
['veilingtransport-documenten','schadeauto-veiling-transport','veilingtransport-belgie','veilingtransport-kosten'])

P('veilingtransport-spanje','Routes','Veilingaankoop laten vervoeren naar Spanje',
'Voertuig of kavel na een veiling naar Spanje laten brengen? Bespreek laadadres, Spaanse bestemming, afhaaldag, lading en ontvangst met ACR.',
'Wilt u uw veilingaankoop niet in België laten eindigen maar naar Spanje laten vervoeren? Geef die eindbestemming meteen door. ACR beoordeelt zo’n internationale transportvraag apart, met de werkelijke route, de aankoopgegevens en de mogelijkheden om op de Spaanse locatie af te leveren.',[
('Noem de uiteindelijke bestemming vanaf het begin','Gebruik een volledig Spaans adres met postcode en een bereikbaar ontvangstcontact. Vermeld of het om het vasteland of een eilandbestemming gaat. Een eilandtraject vraagt andere planning en afzonderlijke afspraken; deze pagina bevestigt geen vaste afvaart, ferryboeking of eilanddienst. Geef toegang, poorten en eventuele lokale ontvangstbeperkingen vooraf door.'),
('Een veilingdead­line en leverwens zijn twee voorwaarden','De aankoop moet op tijd worden afgehaald, terwijl de ontvanger in Spanje mogelijk alleen op bepaalde dagen aanwezig is. Deel beide beperkingen met ACR. Een gewenste leverdatum wordt niet automatisch haalbaar doordat de afhaaldag vastligt. Laat route, eventuele tussenstappen en ontvangst eerst als één volledige uitvoering beoordelen.'),
('Maak de lading geschikt voor een lange route','Voor voertuigen zijn maten, massa, technische toestand en losse accessoires nodig. Voor goederen geeft u aantal eenheden, verpakking en laad- en losmiddelen door. Meld bijzondere bescherming of behandeling voordat de offerte wordt gemaakt. Verpakken, opslag en aanvullende handelingen worden niet stilzwijgend inbegrepen in een internationale rit.'),
('Laat planning en prijs concreet bevestigen','Deze pagina belooft geen vaste wekelijkse route of standaardtarief naar heel Spanje. ACR bespreekt de haalbare uitvoering en beschikbare planning op basis van uw aanvraag. Verandert een afhaalvenster of blijkt de lading anders dan beschreven, geef dat onmiddellijk door. De afspraken moeten passen bij de actuele aankoop en de uiteindelijke bestemming.')],
['Laadadres van de veilingaankoop','Volledig Spaans eindadres en ontvangstcontact','Vasteland of eiland duidelijk vermeld','Afhaaldag en gewenste ontvangstperiode','Maten, massa, toestand en bijzondere behandeling'],
[('Kan het rechtstreeks naar mijn adres in Spanje?','Dat kunt u als gewenste uitvoering opgeven. ACR beoordeelt de route, bereikbaarheid en planning en bevestigt wat voor uw opdracht mogelijk is.'),('Is een vaste vertrekdag gegarandeerd?','Nee. Er wordt hier geen vaste vertrekfrequentie beloofd. Afhaling en levering worden per opdracht afgestemd en bevestigd.')],
['veilingtransport-italie','veilingtransport-frankrijk-belgie','camper-veiling-transport','veilingtransport-documenten'])

P('veilingtransport-italie','Routes','Transport van een veilingaankoop naar Italië',
'Veilingauto, motor of goederen naar Italië laten leveren? ACR beoordeelt de volledige route met laadadres, bestemming, afhaalvenster en ontvangst.',
'Een aankoop op een veiling kan een eindbestemming in Italië hebben. Geef die bestemming meteen mee in uw aanvraag, zodat transport en ontvangst als één opdracht worden bekeken. ACR bevestigt de mogelijkheden na beoordeling van de lading, route en beschikbare planning.',[
('Gebruik een volledig Italiaans losadres','Een regio of grote stad is niet voldoende voor de beoordeling van aflevering. Bezorg straat, postcode en een rechtstreeks bereikbaar contact. Meld een binnenplaats, smalle toegangsweg, hoogtebeperking of bijzonder ontvangstvenster. Gaat het om een eiland of een locatie met een aanvullende oversteek, vermeld dat expliciet voor een aparte beoordeling.'),
('Maak de planning aan beide kanten zichtbaar','Noteer de uiterste afhaaldag van het kavel en de dagen waarop de Italiaanse ontvanger aanwezig is. Geef ook eventuele verplichte afspraken op de laadlocatie door. De rit wordt pas bevestigd als deze voorwaarden samen passen. Een aankoop die snel weg moet, kan niet zonder overleg worden gekoppeld aan elke gewenste leverperiode.'),
('Vul de technische gegevens zorgvuldig aan','Bij auto’s en motoren zijn voertuiggegevens, wielbeweging, sleutels en eventuele schade belangrijk. Voor machines en andere goederen zijn massa, transportmaten en laadondersteuning nodig. Losse onderdelen horen op de lijst. Geef een onzekere massa of onduidelijke verpakking niet als bevestigd feit door; laat de verkoper de ontbrekende informatie aanvullen.'),
('Bespreek de volledige uitvoering','Vraag wat het vervoer omvat en welke aanvullende handelingen apart moeten worden geregeld. Binnenplaatsen, opslag, demontage en installatie zijn geen vanzelfsprekende onderdelen van een rit naar Italië. Deze pagina claimt geen vaste maandroute of beschikbaarheid op elke dag. ACR bevestigt de concrete planning en prijs voor uw opdracht.')],
['Exact laadadres en veilingreferentie','Italiaans losadres met postcode en telefoonnummer','Afhaaldeadline en ontvangstperiode','Voertuigtoestand of maten en massa van goederen','Bereikbaarheid en laad- en losondersteuning'],
[('Kan een veilingmotor naar Italië worden aangevraagd?','Ja. Bezorg model, massa, breedte, toestand en beide adressen. ACR beoordeelt de transportuitvoering en planning vóór bevestiging.'),('Is tijdelijke opslag onderweg inbegrepen?','Daar wordt geen standaardtoezegging over gedaan. Geef een opslagwens vooraf door en laat een eventuele aanvullende afspraak afzonderlijk bevestigen.')],
['veilingtransport-spanje','motor-veiling-transport','veilingtransport-kosten','afhaaldag-veiling-regelen'])

P('afhaaldag-veiling-regelen','Voorbereiding','Afhaaldag van een veiling goed regelen',
'Vaste afhaaldag of tijdslot voor uw veilingaankoop? Regel vrijgave, laadlijst, contactpersoon en transportplanning voordat de deadline dichtbij komt.',
'De afhaaldag is vaak de schakel tussen aankoop en transport. Een korte deadline vraagt niet alleen snelheid, maar ook complete informatie: wat mag worden meegenomen, door wie, op welke plek en binnen welk tijdvak? Met die voorbereiding kan ACR een haalbare uitvoering beoordelen.',[
('Lees het tijdvak bij uw eigen kavel','Een veiling kan verschillende locaties of afspraken hebben. Gebruik daarom de afhaalinformatie van de toegewezen aankoop, samen met uw afhaaldocument. Noteer datum, begin- en eindtijd en eventuele aanmelding. Twijfelt u tussen een algemene veilingdatum en een individuele afspraak, laat de verkoper of het platform bevestigen welke instructie geldt.'),
('Zorg voor vrijgave vóór vertrek','Controleer welke bevestiging of documenten de afhaler nodig heeft en of het kavel daadwerkelijk mag worden afgegeven. Geef de locatiecontactpersoon en een bereikbaar nummer mee. Transport plannen is geen vervanging voor betaling of vrijgave. Een rit laten vertrekken zonder die duidelijkheid kan tot een vergeefse afhaling leiden.'),
('Maak de lading gereed binnen hetzelfde venster','Vermeld of goederen nog moeten worden verpakt, losgemaakt of tot aan de laadplaats gebracht. Vraag wie daarvoor beschikbaar is en hoeveel tijd de voorbereiding vraagt. Voor een voertuig moet de technische toestand bekend zijn. Het tijdslot mag niet worden ingevuld alsof alle voorbereidende handelingen automatisch bij aankomst van de transporteur worden opgelost.'),
('Leg vast wat u doet bij wijzigingen','Meld een gewijzigd tijdvak, extra kavel of ontbrekende sleutel direct aan ACR. Spreek af welke informatie nog nodig is voordat de rit definitief wordt bevestigd. De transporteur kan de laadplanning aanpassen binnen de haalbare mogelijkheden, maar beslist niet over uitzonderingen op de afhaalvoorwaarden van het platform.')],
['Datum en tijdvak van het specifieke kavel','Eventuele verplichte reservering of aanmelding','Vrijgavegegevens beschikbaar vóór vertrek','Lading voorbereid en laadhulp bevestigd','Bereikbare contactpersonen bij wijziging'],
[('Kunnen jullie vandaag nog een kavel ophalen?','Bel met kavellink, adres, toestand en deadline. ACR bekijkt de beschikbare planning; een dringende aanvraag is geen automatische garantie op afhaling diezelfde dag.'),('Kan een gemiste afhaaldag zomaar worden verplaatst?','Dat bepaalt de betrokken afhaallocatie of het platform. Vraag daar eerst om duidelijkheid en geef de bevestigde afspraak daarna door voor de transportplanning.')],
['veilingtransport-documenten','veilingtransport-checklist','meerdere-kavels-ophalen','veilingtransport-kosten'])

P('veilingtransport-documenten','Voorbereiding','Documenten voor afhaling van veilingaankopen',
'Welke gegevens heeft uw veilingtransporteur nodig? Bereid kavelreferentie, vrijgave, afhaalafspraak, contactgegevens en de lijst van mee te geven stukken voor.',
'De vereiste afhaalstukken verschillen per platform, locatie en aankoop. Deze praktische gids helpt om de overdracht aan de transporteur voor te bereiden. Gebruik altijd de actuele instructies van uw eigen kavel en laat onduidelijkheden door de verkoper of het platform bevestigen.',[
('Maak een compacte afhaalbundel','Verzamel kavellink, kavelnummer, laadadres, tijdvak en de gevraagde vrijgavegegevens. Voeg de naam en het telefoonnummer van de afhaalcontactpersoon toe. Als meerdere kavels samen worden opgehaald, geef dan per kavel aan wat erbij hoort. Zo hoeft de afhaler niet uit verschillende losse berichten te raden welke aankoop mag worden meegenomen.'),
('Deel alleen gegevens die nodig zijn voor de afhaling','Een accountwachtwoord is geen normaal afhaaldocument. Bezorg de documenten, QR-code of referenties die de betrokken locatie daadwerkelijk voor de afgifte vraagt. Controleer of u een derde moet aanmelden of machtigen. U hoeft bij een eerste offerteaanvraag geen onnodige identiteits- of accountgegevens mee te sturen; begin met de kavel- en transportgegevens.'),
('Maak mee te geven stukken en onderdelen controleerbaar','Bij een voertuig vermeldt u welke sleutels en documenten de verkoper volgens de aankoop zal overdragen. Voor machines en goederen noteert u losse onderdelen, accessoires en eventuele handleidingen. Geef ontbrekende stukken vooraf door. De transporteur neemt goederen mee volgens de afgesproken afhaling; hij garandeert daarmee niet de volledigheid of juridische bruikbaarheid van de aankoopadministratie.'),
('Maak onderscheid met registratie en andere administratie','Transportdocumentatie, koopdocumenten en registratie van een voertuig zijn verschillende onderwerpen. Deze pagina is geen juridisch of fiscaal advies en belooft geen inschrijving, keuring of belastingafhandeling. Heeft u een bijzondere administratieve vraag, laat de actuele vereisten bij de juiste instantie of betrokken partij bevestigen en stem de gevolgen voor de afhaling af.')],
['Kavellink en uniek kavelnummer','Exact laadadres en afhaalvenster','Vrijgavegegevens volgens de actuele instructies','Aanmelding of machtiging waar vereist','Lijst van sleutels, documenten en losse delen'],
[('Moet ik mijn veilingaccount delen?','Nee. Deel geen wachtwoord. Gebruik de afhaalstukken of referenties die het platform voor afhaling door een derde voorschrijft.'),('Zijn de documenten bij elk platform hetzelfde?','Nee. Controleer de instructies van uw concrete aankoop. ACR moet vooraf weten welke gegevens op de laadlocatie voor uw afhaling nodig zijn.')],
['troostwijk-transport','vavato-transport','auctim-transport','afhaaldag-veiling-regelen'])

P('laden-lossen-veiling','Voorbereiding','Laden en lossen bij veilingtransport voorbereiden',
'Wie laadt en wie lost uw veilingaankoop? Leg toegang, hulpmiddelen, bedieners, ondergrond en voorbereidende werkzaamheden vooraf vast met ACR.',
'Een transport kan pas goed worden beoordeeld als de lading op het laadpunt kan komen en op de bestemming kan worden aangenomen. De aanwezigheid van een vrachtwagen lost ontbrekende voorbereiding niet automatisch op. Beschrijf daarom laden en lossen als twee afzonderlijke onderdelen van uw aanvraag.',[
('Breng het hele traject in beeld','Laat zien waar het kavel staat en hoe het voertuig de laadplaats bereikt. Denk aan verdieping, deuren, loopafstand, drempels en zachte ondergrond. Een machine in de werkplaats en dezelfde machine buiten naast een laadzone zijn verschillende situaties. Vraag ook of een poort of terrein tijdens het afgesproken venster toegankelijk blijft.'),
('Noem materieel én de persoon die het bedient','Een heftruck op een terrein is niet automatisch beschikbaar voor uw afhaling. Vraag welke ondersteuning de locatie bevestigt, of zij bij het gewicht en de afmetingen past en wie deze uitvoert. Doe hetzelfde aan de loszijde. Vermeld het als een hulpmiddel nog moet worden geregeld; beschikbaarheid mag geen onbesproken aanname blijven.'),
('Spreek de voorbereiding van de lading af','Goederen moeten in de afgesproken transporttoestand gereedstaan. Losmaken, demonteren, verpakken en het verplaatsen door een gebouw zijn aparte handelingen. Voor voertuigen zijn wielbeweging en sleutels van belang. Laat ACR weten wat nog niet klaar is, zodat de uitvoering en prijs niet op een verkeerde veronderstelling worden bevestigd.'),
('Geef de ontvanger een uitvoerbare taak','Vertel wie de levering aanneemt, waar de lading mag komen en welke hulp beschikbaar is. Meld een smalle straat, een niet-verharde oprit of een beperkte ontvangsttijd. Binnenplaatsen, positioneren en installeren vallen alleen binnen de opdracht als ze apart zijn afgesproken. Een losplek moet passen bij de afgesproken handling en bij de lading.')],
['Standplaats van het kavel en route tot de laadplaats','Vrije toegang met passende poorten en ondergrond','Bevestigde hulpmiddelen en geschikte bedieners','Voorbereiding, verpakking of demontage geregeld','Ontvanger, losmiddelen en duidelijke losplek'],
[('Betekent een aanwezige heftruck dat laden geregeld is?','Nee. Bevestig beschikbaarheid, geschiktheid en bediening voor uw specifieke kavel en tijdslot.'),('Is het binnenzetten van een machine inbegrepen?','Dat is een afzonderlijke vraag. Geef het volledige traject en de gewenste plaatsing door en laat bevestigen welke werkzaamheden bij de opdracht horen.')],
['machine-veiling-transport','pallet-veiling-transport','niet-rijdende-veilingauto','veilingtransport-kosten'])

P('veilingtransport-offerte-voor-bieden','Voorbereiding','Transportofferte aanvragen vóór u biedt',
'Voorkom een onvolledig aankoopbudget: laat vóór uw bod de route, kavelmaten, technische toestand, afhaaldag en transportmogelijkheden beoordelen door ACR.',
'Een aantrekkelijke veilingprijs vertelt niet wat het ophalen en afleveren zal vragen. Met een transportbeoordeling vóór uw bod kunt u de praktische haalbaarheid meenemen in uw beslissing. ACR kan uw aanvraag bekijken zodra kavellink, route, lading en afhaalvoorwaarden voldoende duidelijk zijn.',[
('Stuur de gegevens door zolang vragen nog kunnen worden gesteld','Bezorg de kavellink, beschikbare maten en massa, de standplaats en uw gewenste bestemming. Vraag de verkoper om ontbrekende gegevens zoals wielbeweging, verpakking of laadhulp. Een beoordeling is betrouwbaarder wanneer onzekerheden zichtbaar zijn. Een screenshot met alleen de huidige biedprijs zegt vrijwel niets over de benodigde transportuitvoering.'),
('Laat uw budget meer omvatten dan de route','Denk aan voorbereidend werk dat nog niet is geregeld: verpakken, demonteren, een machine naar buiten brengen of hulpmiddelen bij lossen. Vraag welke handelingen in de transportprijs zijn opgenomen en welke niet. Controleer de btw-vermelding op de offerte. De koopprijs en het vervoer blijven twee afzonderlijke onderdelen van uw beslissing.'),
('Controleer de harde afhaalvoorwaarden','Noteer de afhaaldag en het tijdvak vóór u ervan uitgaat dat transport later gemakkelijk in te passen is. Geef een beperkte ontvangstperiode op uw bestemming ook mee. Een transportbeoordeling vóór de veiling is geen garantie dat capaciteit onbeperkt beschikbaar blijft. Laat na toewijzing de actuele planning en opdracht bevestigen.'),
('Bevestig opnieuw wanneer het kavel verandert','Een andere technische toestand, extra onderdelen of een gewijzigd afhaaladres kan de eerdere beoordeling veranderen. Geef de uiteindelijke toegewezen selectie aan ACR door. Stuur de nieuwe afhaalgegevens mee en benoem wat afwijkt van de eerste aanvraag. Zo wordt een voorlopige inschatting niet onterecht behandeld als een definitieve afspraak voor een andere lading.')],
['Kavellink en voorgenomen selectie vóór het bieden','Beschikbare maten, massa en technische toestand','Werkelijke laadlocatie en gewenste bestemming','Afhaaldatum met strikte voorwaarden','Nog te regelen voorbereiding en ontvangst'],
[('Is een voorlopige prijs meteen een vaste boeking?','Nee. Laat na de toewijzing de definitieve gegevens, uitvoering, prijs en beschikbare planning bevestigen.'),('Wat als ik het kavel niet win?','Geef dat door wanneer u al over planning hebt gesproken. Een beoordeling van een mogelijke aankoop moet duidelijk worden onderscheiden van een bevestigde transportopdracht.')],
['veilingtransport-kosten','veilingtransport-checklist','afhaaldag-veiling-regelen','meerdere-kavels-ophalen'])

P('veilingtransport-checklist','Voorbereiding','Checklist: veilingaankoop laten ophalen',
'Gebruik de praktische ACR-checklist voor uw veilingtransport: kavels, route, afhaaldag, vrijgave, laadbaarheid, verpakking en ontvangst in één overzicht.',
'Een complete transportaanvraag bespaart heen-en-weer berichten en voorkomt dat een belangrijke beperking pas op de laadplaats blijkt. Gebruik deze checklist vóór het aanvragen en controleer de gegevens opnieuw na toewijzing. Onderaan kunt u uw aanvraag klaarzetten voor WhatsApp, e-mail of een afdruk.',[
('Stap 1: leg aankoop en route vast','Noteer platform, kavellink en alle te vervoeren kavelnummers. Schrijf laad- en losadres volledig uit, inclusief postcode en eventuele poortinformatie. Geef per locatie een bereikbaar contact op. Combineert u aankopen, groepeer de transporteenheden dan per adres en noteer hun afhaaldagen afzonderlijk.'),
('Stap 2: beschrijf de laadbaarheid','Voor voertuigen vult u merk, model, uitvoering en bekende massa in. Noteer starten, rollen, sturen, remmen en sleutels als aparte gegevens. Voor goederen beschrijft u aantallen, buitenmaten, massa en verpakking per eenheid. Voeg foto’s toe die de huidige toestand en het traject tot aan de laadplaats verduidelijken.'),
('Stap 3: controleer tijdslot en vrijgave','Bezorg het bevestigde afhaalvenster en vraag welke gegevens de afhaler moet meenemen. Controleer of de aankoop mag worden vrijgegeven. Noteer wie voorbereiding, demontage, verpakking en laadhulp regelt. Deel geen accountwachtwoord wanneer een afhaaldocument, referentie of QR-code bedoeld is voor de afhaling.'),
('Stap 4: maak ontvangst en bevestiging concreet','Laat de ontvanger weten wat arriveert en wat nodig is om het aan te nemen. Controleer de losplek en beschikbare hulp. Vraag ACR daarna om bevestiging van uitvoering, prijs en planning. Verandert iets aan lading of tijdslot, meld het vóór vertrek. De checklist helpt voorbereiden en vervangt geen bevestigde opdracht.')],
['Alle kavelnummers met actuele links','Twee volledige adressen en locatiecontacten','Maten, massa, toestand en foto’s','Afhaaldag, vrijgave en voorbereiding bevestigd','Losplek, ontvangst en opdrachtbevestiging'],
[('Kan ik de ingevulde checklist direct versturen?','U kunt hieronder een tekstoverzicht maken. Een WhatsApp- of e-mailknop opent uw eigen toepassing; u verzendt het bericht zelf. De website verstuurt dit formulier niet automatisch.'),('Is alles geregeld wanneer de checklist compleet is?','Nee. ACR moet de uitvoering, prijs en planning nog bevestigen. De checklist verzamelt de gegevens die daarvoor nodig zijn.')],
['veilingtransport-documenten','laden-lossen-veiling','veilingtransport-offerte-voor-bieden','veilingtransport-acr-informatie'])

P('veelgestelde-vragen-veilingtransport','Voorbereiding','Veelgestelde vragen over veilingtransport',
'Duidelijke antwoorden over veilingtransport met ACR: aanvragen, prijs, platformen, niet-rijdende voertuigen, goederen, documenten en internationale levering.',
'Hier vindt u korte antwoorden op terugkerende vragen van kopers die hun veilingaankoop willen laten ophalen. De antwoorden verwijzen naar uitgebreidere uitleg per onderwerp. Uitvoering, prijs en planning worden altijd voor de concrete opdracht bevestigd; een algemene pagina is geen transportreservering.',[
('Welke aanvraag hoort bij uw aankoop?','Voor een auto, motor, bestelwagen of camper begint u bij voertuigtransport. Geef daarbij de technische toestand en aanwezige sleutels door. Voor pallets, machines en inventaris zijn fysieke eenheden, buitenmaten, massa en verpakking nodig. Koopt u verschillende soorten kavels, zet ze dan op één duidelijke lijst en laat de combinatie beoordelen.'),
('Wat doet ACR en wat blijft bij de veiling?','U spreekt vervoer rechtstreeks met ACR af. Het platform of de verkoper behandelt de aankoop en de voorwaarden voor afgifte. Deze website claimt geen officiële vertegenwoordiging van Troostwijk, Vavato of Auctim. Een aangevraagd transport verandert de vrijgave of afhaaldag van uw aankoop niet zonder bevestiging van de betrokken partij.'),
('Welke antwoorden kunt u niet uit een algemene prijslijst halen?','De route, technische toestand, maten en tijdsloten verschillen per kavel. Daarom staat er geen universeel bedrag voor elke veilingauto of pallet op deze site. Geef de volledige opdracht door, inclusief laden en lossen. Bespreek bijkomende werkzaamheden apart en laat duidelijk vermelden welke uitvoering en prijs zijn bevestigd.')],
['Kies de uitgebreide gids voor uw type lading','Gebruik de afhaalinformatie van het concrete kavel','Vraag onduidelijke gegevens aan de verkoper','Laat ACR de rit, prijs en planning bevestigen'],
[('Hoe vraag ik veilingtransport aan bij ACR?','Stuur de kavellink, laad- en losadres, afhaalvenster en ladinggegevens. U kunt bellen op 0471 37 90 64, WhatsApp gebruiken of het centrale ACR-offerteformulier openen.'),('Kan ik aanvragen voordat ik de veiling win?','Ja. Laat de haalbaarheid beoordelen met de beschikbare gegevens en bevestig na toewijzing de uiteindelijke selectie en planning.'),('Kunnen niet-rijdende voertuigen worden aangevraagd?','Ja. Vermeld of het voertuig kan rollen, sturen en remmen, of sleutels aanwezig zijn en welke schade of lekkages bekend zijn. De laadwijze wordt eerst beoordeeld.'),('Kan ik ook goederen en machines laten beoordelen?','Ja. Geef aantallen, maten, massa, verpakking, toegang en beschikbare hulpmiddelen door. Zwaar of specialistisch werk wordt niet zonder afzonderlijke beoordeling toegezegd.'),('Wat moet ik regelen voor de afhaaldag?','Controleer het tijdvak, de vrijgavegegevens, bereikbaarheid en voorbereiding van de lading. Geef een bereikbaar contact op en zorg dat de ontvanger de levering kan aannemen.'),('Wordt internationaal transport aangeboden?','U kunt routes vanuit België, Nederland, Duitsland, Luxemburg en Frankrijk aanvragen en verdere levering, onder meer naar Spanje of Italië, bespreken. Elke concrete uitvoering wordt afzonderlijk bevestigd.'),('Zijn verpakking, demontage en installatie inbegrepen?','Alleen als die werkzaamheden uitdrukkelijk zijn afgesproken. Een transportprijs is geen automatische toezegging voor alle voorbereidende en aanvullende taken.'),('Wat bepaalt de prijs?','De volledige route, hoeveelheid lading, maten, massa, toestand, tijdvensters, laad- en loswerk en eventuele extra stops bepalen de beoordeling.')],
['veilingtransport-checklist','veilingtransport-kosten','veilingtransport-voertuigen','veilingtransport-goederen'])

P('veilingtransport-acr-informatie','Voorbereiding','Veilingtransport by ACR: diensten en contactgegevens',
'Feitelijk overzicht van Veilingtransport by ACR: contact, aanvraaggegevens, voertuigen, goederen, routes en afspraken over afhaling en levering.',
'Veilingtransport.be is een website binnen het ACR-netwerk voor aanvragen rond het ophalen en leveren van veilingaankopen. Dit overzicht bundelt de contactgegevens en afbakening van de dienst. Het is bedoeld voor kopers, zakelijke ontvangers en zoekdiensten die snel willen begrijpen wat op deze website wordt aangeboden.',[
('Wie is het aanspreekpunt?','Transportaanvragen via deze website worden met ACR besproken. Het telefoonnummer is +32 471 37 90 64 en het contactadres is depannageacr@hotmail.com. De offerteknoppen verwijzen naar het centrale formulier op autorepatriering.be. Een WhatsApp-link opent uw eigen toepassing; u verstuurt het bericht zelf. Deze site bevestigt niet automatisch een rit na het openen van een contactknop.'),
('Welke transportvragen kunnen worden voorgelegd?','De website behandelt aanvragen voor veilingvoertuigen, waaronder auto’s, motoren, bestelwagens en campers, en voor goederen zoals pallets, machines en inventaris. Dit is een opsomming van te beoordelen aanvragen, geen onbeperkte acceptatie van elke afmeting, massa of toestand. De feitelijke lading en beschikbare middelen bepalen welke uitvoering kan worden bevestigd.'),
('Hoe worden routes en werkzaamheden afgesproken?','België, Nederland, Duitsland en Luxemburg behoren tot de routes waarover de website informatie geeft. Ook afhaling in Frankrijk en verdere internationale levering naar onder meer Spanje of Italië kunnen worden aangevraagd. Er wordt geen vaste vertrekfrequentie of automatische beschikbaarheid beloofd. Voorbereiding, verpakking, demontage, opslag en installatie zijn alleen inbegrepen na een afzonderlijke afspraak.'),
('Wat is de relatie met veilingplatformen?','Namen zoals Troostwijk, Vavato en Auctim worden gebruikt om kopers bij de voorbereiding te helpen. Deze website claimt geen officiële samenwerking, erkenning of vertegenwoordiging van deze platformen. Aankoop, betaling en vrijgave worden bij de betrokken partijen geregeld. ACR bevestigt de concrete transportopdracht met de klant, inclusief uitvoering, prijs en haalbare planning.')],
['Website: https://www.veilingtransport.be/','Telefoon en WhatsApp: +32 471 37 90 64','Contactmail: depannageacr@hotmail.com','Aanvraag: kavel, route, tijdslot en ladinggegevens','Rit pas vast na bevestiging van uitvoering, prijs en planning'],
[('Is dit informatie voor AI-zoekdiensten?','Dit openbare feitenoverzicht is voor iedereen leesbaar, ook voor zoekdiensten. Dezelfde contactgegevens en dienstafbakening worden op de gewone pagina’s gebruikt.'),('Garandeert deze pagina een plaats in AI-antwoorden?','Nee. De site biedt heldere en controleerbare informatie, maar zoekdiensten bepalen zelf welke bronnen zij tonen. Een AI-vermelding of zoekpositie wordt niet gegarandeerd.')],
['veelgestelde-vragen-veilingtransport','veilingtransport-checklist','veilingtransport-kosten','veilingtransport-voertuigen'])
